(window.EX_CHUNKS=window.EX_CHUNKS||{})["b01"]={"日历":[["他每天都在撕日历上的日期。","ئۇ ھەر كۈنى كۈنتەرۋىدىكى چېسلانى يۇلۇپ تاشلايدۇ.","u her küni künterwidiki chéslani yulup tashlaydu."]],"埋葬":[["人们为牺牲的英雄举行了隆重的埋葬仪式。","كىشىلەر قۇربان بولغان قەھرىمانلار ئۈچۈن تەنتەنىلىك دەپنە مۇراسىمى ئۆتكۈزدى.","kishiler qurban bolghan qehrimanlar üchün tentenilik depne murasimi ötküzdi."]],"沼泽":[["探险家们小心翼翼地穿过沼泽地。","تەتقىقاتچىلار ساقلىق بىلەن سازلىقتىن ئۆتتى.","tetqiqatchilar saqliq bilen sazliqtin ötti."]],"座右铭":[["天道酬勤”是他的座右铭。","«تەڭرى ئەمگەكنى مۇكاپاتلايدۇ» ئۇنىڭ شۇئارى.","«tengri emgekni mukapatlaydu» uning shuari."]],"咁":[["你咁做是不对的。","سېنىڭ بۇنداق قىلغىنىڭ توغرا ئەمەس.","séning bundaq qilghining toghra emes."]],"戁":[["他担心事情会戁变。","ئۇ ئىشنىڭ ناچارلىشىشىدىن ئەنسىرىدى.","u ishning nacharlishishidin ensiridi."]],"橁":[["这种橁木适合用来做家具。","بۇ خىل چىلان ياغىچى ئۆي جاھازىسى ياساشقا ماس كېلىدۇ.","bu xil chilan yaghichi öy jahazisi yasashqa mas kélidu."]],"歁":[["他歁地接受了批评。","ئۇ تەنقىدنى قوبۇل قىلدى.","u tenqidni qobul qildi."]],"粁":[["粁米的颗粒饱满均匀。","سىمىننىڭ دانىلىرى تولۇق ۋە تەكشى.","siminning daniliri toluq we tekshi."]],"苁":[["苁蓉是一种珍贵的中药材。","سېرىق ئوت قىممەتلىك بىر خىل جۇڭگو دورىسى.","sériq ot qimmetlik bir xil junggo dorisi."]],"瀁":[["瀁水是一条清澈见底的小溪。","ئاقار سۈيى تەگى كۆرۈنگەن سۈزۈك بىر كىچىك ئېقىن.","aqar süyi tegi körüngen süzük bir kichik éqin."]],"䍁":[["䍁是一种古老的纺织工具。","جۈەن قەدىمىي بىر توقۇمىچىلىق قورالىدۇر.","jüen qedimiy bir toqumichiliq qoralidur."]],"艁":[["艁船常用于水上运输。","زاۋ كېمىسى كۆپىنچە سۇ ئۈستى توشۇشتا ئىشلىتىلىدۇ.","zaw kémisi köpinche su üsti toshushta ishlitilidu."]],"跁":[["他跁着脚走路。","ئۇ پۇتىنى ئاقساپ ماڭدى.","u putini aqsap mangdi."]],"一旁":[["他站在一旁观看比赛。","ئۇ بىر چەتتە تۇرۇپ مۇسابىقىنى كۆردى.","u bir chette turup musabiqini kördi."]],"一醉方休":[["他非要喝到一醉方休不可。","ئۇ مەست بولمىغۇچە ئىچمەي قويمايدۇ.","u mest bolmighuche ichmey qoymaydu."]],"一言抄百总":[["他一言抄百总，总结得非常到位。","ئۇ بىر ئېغىز سۆز بىلەن يۈزنى خۇلاسىلىدى، خۇلاسىسى ناھايىتى ئورۇنلۇق بولدى.","u bir éghiz söz bilen yüzni xulasilidi, xulasisi nahayiti orunluq boldi."]],"三次方":[["三次方在几何中代表体积的计算。","ئۈچىنچى دەرىجە گېئومېتىرىيەدە ھەجىم ھېسابلاشنى ئىپادىلەيدۇ.","üchinchi derije géométiriyede hejim hésablashni ipadileydu."]],"三江并流":[["三江并流是世界自然遗产之一。","ئۈچ دەريا قوشۇلۇشى دۇنيانىڭ تەبىئىي مىراسلىرىنىڭ بىرىدۇر.","üch derya qoshulushi dunyaning tebiiy miraslirining biridur."]],"三棱草":[["三棱草是一种常见的野生植物。","ئۈچ قىرلىق ئوت ئومۇمىي ياۋا ئۆسۈملۈك.","üch qirliq ot omumiy yawa ösümlük."]],"上一号":[["请上一号选手上台。","بىرىنچى نومۇرلۇق مۇسابىقىچىنى سەھنىگە چىقىڭ.","birinchi nomurluq musabiqichini sehnige chiqing."]],"不合时宜":[["这话说的不合时宜。","بۇ گەپ ۋاقتىغا مۇۋاپىق ئەمەس.","bu gep waqtigha muwapiq emes."]],"不大离":[["这个说法不大离奇，听起来合理。","بۇ دېيىش ئانچە غەلىتە ئەمەس، ئاڭلىتىلىشىچە مۇۋاپىق.","bu déyish anche ghelite emes, anglitilishiche muwapiq."]],"上合组织":[["上合组织推动了区域合作。","شاڭخەي ھەمكارلىق تەشكىلاتى رايون ھەمكارلىقىنى ئىلگىرى سۈردى.","shangxey hemkarliq teshkilati rayon hemkarliqini ilgiri sürdi."]],"上同调":[["这个理论需要上同调分析。","بۇ نەزەرىيەگە كوھومولوگىيە تەھلىلى كېرەك.","bu nezeriyege kohomologiye tehlili kérek."]],"上鞋":[["她正在给鞋子穿上鞋带，准备出门。","ئۇ ئايىغىغا باغ يېپ ئۆيدىن چىقىشقا تەييارلىق قىلماقتا.","u ayighigha bagh yép öydin chiqishqa teyyarliq qilmaqta."]],"不差":[["这家餐厅的饭菜味道不差，值得推荐。","بۇ رېستوراننىڭ تامىقىنىڭ تەمى يامان ئەمەس، تەۋسىيە قىلىشقا ئەرزىيدۇ.","bu réstoranning tamiqining temi yaman emes, tewsiye qilishqa erziydu."]],"不明觉厉":[["不明觉厉啊！","چۈشەنمىسەممۇ ھەيران قالدىم!","chüshenmisemmu heyran qaldim!"]],"不打紧":[["这点事不打紧。","بۇ ئىش ھېچقانچە ئەھمىيەتسىز.","bu ish héchqanche ehmiyetsiz."]],"不问":[["他从不问别人的私事。","ئۇ ھەرگىز باشقىلارنىڭ شەخسىي ئىشلىرىنى سورىمايدۇ.","u hergiz bashqilarning shexsiy ishlirini sorimaydu."]],"世宗":[["世宗是一位贤明的君主。","شىزۇڭ ئەقىللىق پادىشاھ ئىدى.","shizung eqilliq padishah idi."]],"不当紧":[["天气冷，但穿着不当紧。","ھاۋا سوغۇق، ئەمما كىيىم-كېچەك مۇھىم ئەمەس.","hawa soghuq, emma kiyim-kéchek muhim emes."]],"不醉不归":[["今晚不醉不归，尽情狂欢！","بۈگۈن كېچە مەست بولمىغۇچە قايتمايمىز، خۇشاللىق بىلەن ئوينىلايمىز!","bügün kéche mest bolmighuche qaytmaymiz, xushalliq bilen oynilaymiz!"]],"世贸大厦":[["世贸大厦的倒塌震惊了全世界。","دۇنيا سودا بىناسىنىڭ يىمىرىلىشى پۈتۈن دۇنيانى ھەيران قالدۇردى.","dunya soda binasining yimirilishi pütün dunyani heyran qaldurdi."]],"丙基":[["丙基常用于有机合成反应中。","پروپىل گۇرۇپپىسى ئورگانىك بىرىكمە رېئاكسىيەلىرىدە كۆپ ئىشلىتىلىدۇ.","propil guruppisi organik birikme réaksiyeliride köp ishlitilidu."]],"丢眉丢眼":[["他因紧张而显得丢眉丢眼。","ئۇ ھاياجانلانغانلىقتىن كۆزلىرى ئېچىلىپ-يۇمۇلۇپ قالدى.","u hayajanlanghanliqtin közliri échilip-yumulup qaldi."]],"中央日报":[["中央日报是权威新闻媒体。","مەركىزىي كۈندىلىك گېزىت نوپۇزلۇق خەۋەر تاراتقۇسىدۇر.","merkiziy kündilik gézit nopuzluq xewer taratqusidur."]],"中世纪":[["中世纪是欧洲历史上的重要时期。","ئوتتۇرا ئەسىر ياۋروپا تارىخىدىكى مۇھىم بىر دەۋر.","ottura esir yawropa tarixidiki muhim bir dewr."]],"中正纪念堂":[["中正纪念堂是台北的重要地标。","جۇڭجېڭ خاتىرە سارىيى تەيبېينىڭ مۇھىم يەر بەلگىسىدۇر.","jungjéng xatire sariyi teybéyning muhim yer belgisidur."]],"中美":[["中美关系日益密切。","جۇڭگو-ئامېرىكا مۇناسىۋىتى كۈندىن-كۈن يېقىنلىشىۋاتىدۇ.","junggo-amérika munasiwiti kündin-kün yéqinlishiwatidu."]],"串音":[["吉他出现了串音问题。","گىتاردا ئارىلىشىش ئاۋاز مەسىلىسى كۆرۈلدى.","gitarda arilishish awaz mesilisi körüldi."]],"主权国家":[["主权国家拥有独立的领土和政权。","ئىگىلىك ھوقۇقلۇق دۆلەت مۇستەقىل زېمىن ۋە ھۆكۈمرانلىققا ئىگە.","igilik hoquqluq dölet musteqil zémin we hökümranliqqa ige."]],"中华字海":[["《中华字海》收录了大量汉字。","«جۇڭخۇا ھەرپ دېڭىزى» كۆپ مىقداردىكى خەنزۇ يېزىقىنى توپلىغان.","«jungxua herp déngizi» köp miqdardiki xenzu yéziqini toplighan."]],"中华攀雀":[["中华攀雀栖息在热带雨林中。","جۇڭخۇا دەرەخ تىپىكى قۇشى ئىسسىق بەلباغ ئورمانلىقىدا ياشايدۇ.","jungxua derex tipiki qushi issiq belbagh ormanliqida yashaydu."]],"乘隙":[["他乘隙溜走，逃过追捕。","ئۇ بوشلۇقتىن پايدىلىنىپ قېچىپ، تۇتۇشتىن قۇتۇلۇپ قالدى.","u boshluqtin paydilinip qéchip, tutushtin qutulup qaldi."]],"乙基":[["乙基是一种常见的化学基团。","ئېتىل گۇرۇپپىسى كۆپ ئۇچرايدىغان خىمىيە گۇرۇپپىسىنىڭ بىرى.","étil guruppisi köp uchraydighan ximiye guruppisining biri."]],"二重":[["二重唱需要两人配合。","ئىككى ئاۋازلىق ئېيتىش ئىككى ئادەمنىڭ ماسلىشىشىنى تەلەپ قىلىدۇ.","ikki awazliq éytish ikki ademning maslishishini telep qilidu."]],"二月份":[["二月份天气逐渐转暖。","فېۋرال ئېيىدا ھاۋا تەدرىجىي ئىللىيدۇ.","féwral éyida hawa tedrijiy illiydu."]],"亡魂":[["亡魂在夜里游荡。","ئۆلگەنلەرنىڭ روھى كېچىدە ئايلىنىپ يۈرىدۇ.","ölgenlerning rohi kéchide aylinip yüridu."]],"交汇处":[["交汇处人流量很大。","قوشۇلغان جاي ئادەم ئېقىمى بەك كۆپ.","qoshulghan jay adem éqimi bek köp."]],"亚利桑那":[["亚利桑那州的首府是菲尼克斯。","ئارىزونا شتاتىنىڭ پايتەختى فىنىكسدۇر.","arizona shtatining paytexti finiksdur."]],"亚哈斯":[["亚哈斯是古代以色列的一位国王。","ئاخاز قەدىمكى ئىسرائىلىيەنىڭ بىر پادىشاھى ئىدى.","axaz qedimki israiliyening bir padishahi idi."]],"亟需":[["灾区亟需更多的物资援助。","ئاپەت رايونىغا تېخىمۇ كۆپ ماتېرىيال ياردىمى زۆرۈر.","apet rayonigha téximu köp matériyal yardimi zörür."]],"京二胡":[["京二胡是中国传统乐器。","جىڭئەرخۇ جۇڭگونىڭ ئەنئەنىۋى چالغۇ ئەسۋابى.","jing'erxu junggoning en'eniwi chalghu eswabi."]],"亨利":[["亨利是一位著名的科学家。","خېنرى داڭلىق ئالىم.","xénri dangliq alim."]],"人贩子":[["人贩子必须受到法律的严惩。","ئادەم سېتىۋاتقانلار چوقۇم قانۇننىڭ قاتتىق جازاسىغا ئۇچرىشى كېرەك.","adem sétiwatqanlar choqum qanunning qattiq jazasigha uchrishi kérek."]],"人民阵线":[["人民阵线致力于社会进步。","خەلق سېپى جەمئىيەت تەرەققىياتى ئۈچۈن تىرىشىدۇ.","xelq sépi jem'iyet tereqqiyati üchün tirishidu."]],"人治":[["人治强调个人权力高于法律。","ئادەم بىلەن باشقۇرۇش شەخسىي ھوقۇقنىڭ قانۇندىن ئۈستۈنلۈكىنى تەكىتلەيدۇ.","adem bilen bashqurush shexsiy hoquqning qanundin üstünlükini tekitleydu."]],"什邡市":[["什邡市以优质的苎麻闻名全国。","شىفاڭ شەھىرى سۈپەتلىك رامى نەسى بىلەن پۈتۈن مەملىكەتكە تونۇلغان.","shifang shehiri süpetlik rami nesi bilen pütün memliketke tonulghan."]],"仇怨":[["两人之间的仇怨由来已久。","ئىككىيلەن ئارىسىدىكى ئۆچمەنلىك ئۇزۇندىن بېرى مەۋجۇت.","ikkiylen arisidiki öchmenlik uzundin béri mewjut."]],"令人鼓舞":[["这个消息令人鼓舞。","بۇ خەۋەر كىشىنى روھلاندۇرىدۇ.","bu xewer kishini rohlanduridu."]],"以逸待劳":[["我们应以逸待劳，等待敌人疲惫。","بىز ئارام ئېلىپ دۈشمەننىڭ ھارغىنلىقىنى كۈتۈشىمىز كېرەك.","biz aram élip düshmenning harghinliqini kütüshimiz kérek."]],"伉俪":[["伉俪情深，令人感动。","ئېرى-خوتۇننىڭ چوڭقۇر مۇھەببىتى كىشىنى تەسىرلەندۈرىدۇ.","éri-xotunning chongqur muhebbiti kishini tesirlendüridu."]],"伊利格瑞":[["伊利格瑞的演讲充满激情。","ئىلىگىرەينىڭ نۇتۇقى ھېسسىياتقا تولغان.","iligireyning nutuqi héssiyatqa tolghan."]],"伏地":[["他伏地观察四周的动静。","ئۇ يەرگە يېتىپ ئەتراپتىكى ھەرىكەتلەرنى كۆزەتتى.","u yerge yétip etraptiki heriketlerni közetti."]],"伯乐":[["伯乐善于发现千里马。","بېلې ياخشى ئاتنى تونۇشقا ماھىر.","bélé yaxshi atni tonushqa mahir."]],"伯邑考":[["伯邑考是周武王的弟弟。","بېيىكاۋ جۇ ۋۇۋاڭنىڭ ئىنىسى.","béyikaw ju wuwangning inisi."]],"布兰森":[["布兰森是一位企业家。","بىرانسون بىر ئىشبىلەرمەن.","biranson bir ishbilermen."]],"佛法僧目":[["佛法僧目是佛教三宝的合称。","بۇددا، قانۇن، ساڭغا بۇددا دىنىنىڭ ئۈچ گۆھىرىنىڭ بىرلىككە كەلگەن ئاتىلىشىدۇر.","budda, qanun, sanggha budda dinining üch göhirining birlikke kelgen atilishidur."]],"作保":[["他愿意作保担保这件事。","ئۇ بۇ ئىشقا كاپالەتلىك قىلىشقا خالىيدۇ.","u bu ishqa kapaletlik qilishqa xaliydu."]],"便池":[["公共厕所的便池需要保持清洁。","ئاممىۋى ھاجەتخانىنىڭ ھاجەت دانىلىرى تازا ساقلىنىشى كېرەك.","ammiwi hajetxanining hajet daniliri taza saqlinishi kérek."]],"修路":[["工人们正在修路，确保交通顺畅。","ئىشچىلار يولنى رېمونت قىلىپ، قاتناشنىڭ راۋان بولۇشىنى كاپالەتكە ئىگە قىلماقتا.","ishchilar yolni rémont qilip, qatnashning rawan bolushini kapaletke ige qilmaqta."]],"个人隐私":[["保护个人隐私至关重要。","شەخسىي مەخپىيەتلىكنى قوغداش ئىنتايىن مۇھىم.","shexsiy mexpiyetlikni qoghdash intayin muhim."]],"候场":[["演员在后台候场。","ئارتىس سەھنىە ئارقىسىدا كۈتۈۋاتىدۇ.","artis sehnie arqisida kütüwatidu."]],"候缺":[["公司正在候缺补人。","شىركەت خىزمەت ئورنى تولۇقلاشنى كۈتۈۋاتىدۇ.","shirket xizmet orni toluqlashni kütüwatidu."]],"傍亮":[["天刚傍亮，他就出门了。","تاڭ سەھەرلەپلا ئۇ ئۆيدىن چىقىپ كەتتى.","tang seherlepla u öydin chiqip ketti."]],"备用":[["请携带备用钥匙以防万一。","ئېھتىيات ئۈچۈن ئالماشتۇرما ئاچقۇچنى ئېلىپ يۈرۈڭ.","éhtiyat üchün almashturma achquchni élip yürüng."]],"备注":[["请在表格中填写备注。","جەدۋەلگە ئىزاھات يېزىڭ.","jedwelge izahat yézing."]],"传输模式":[["选择最佳传输模式。","ئەڭ ياخشى يەتكۈزۈش ئەندىزىسىنى تاللاڭ.","eng yaxshi yetküzüsh endizisini tallang."]],"债主":[["债主有权要求债务人还款。","قەرز بېرىگۈچىنىڭ قەرز ئالغۇچىدىن قەرزنى قايتۇرۇشنى تەلەپ قىلىش ھوقۇقى بار.","qerz bérigüchining qerz alghuchidin qerzni qayturushni telep qilish hoquqi bar."]],"充车":[["车站的公交车已经充车完毕，随时出发。","بېكەتتىكى ئاپتوبۇسلار ئاللىبۇرۇن تولۇق تولدۇرۇلۇپ، ھەر ۋاقىت يولغا چىقىشقا تەييار.","békettiki aptobuslar alliburun toluq toldurulup, her waqit yolgha chiqishqa teyyar."]],"仪卫":[["仪卫队伍整齐划一。","مۇراسىم قوغدىغۇچىلار قاتارى تەكشى ۋە تەرتىپلىك.","murasim qoghdighuchilar qatari tekshi we tertiplik."]],"元数据":[["元数据在计算机系统中起着关键作用。","مېتاداتا كومپيۇتېر سىستېمىسىدا ھالقىلىق رول ئوينايدۇ.","métadata kompyutér sistémisida halqiliq rol oynaydu."]],"先有":[["先有因，后有果。","ئاۋۋال سەۋەب بار، كېيىن نەتىجە بار.","awwal seweb bar, kéyin netije bar."]],"先汉":[["先汉时期文化繁荣。","ئالدىنقى خەن دەۋرىدە مەدەنىيەت گۈللەنگەن.","aldinqi xen dewride medeniyet güllengen."]],"克赖斯特彻奇":[["克赖斯特彻奇是新西兰的重要城市。","كرىستچېرچ يېڭى زېلاندىيەدىكى مۇھىم شەھەر.","kristchérch yéngi zélandiyediki muhim sheher."]],"内线消息":[["他通过内线消息获知真相。","ئۇ ئىچكى خەۋەر ئارقىلىق ھەقىقەتنى بىلدى.","u ichki xewer arqiliq heqiqetni bildi."]],"全文检索":[["系统支持全文检索功能。","سىستېما پۈتۈن تېكىست ئىزدەش ئىقتىدارىنى قوللايدۇ.","sistéma pütün tékist izdesh iqtidarini qollaydu."]],"全国各地":[["全国各地都在庆祝节日。","مەملىكەتنىڭ ھەممە جايلىرىدا بايرام تەبرىكلىنىۋاتىدۇ.","memliketning hemme jaylirida bayram tebrikliniwatidu."]],"两国关系":[["两国关系近年来持续改善。","ئىككى دۆلەت مۇناسىۋىتى يېقىنقى يىللاردا داۋاملىق ياخشىلانماقتا.","ikki dölet munasiwiti yéqinqi yillarda dawamliq yaxshilanmaqta."]],"光绪":[["光绪帝在位期间推行变法。","گۇاڭشۈ ئىمپېراتورى ھۆكۈمرانلىق قىلغان مەزگىلدە ئىسلاھات ئېلىپ بارغان.","guangshü impératori hökümranliq qilghan mezgilde islahat élip barghan."]],"八位元":[["计算机中的八位元组成一个字节。","كومپيۇتېردىكى سەككىز بىت بىر بايىتنى تەشكىل قىلىدۇ.","kompyutérdiki sekkiz bit bir bayitni teshkil qilidu."]],"八带鱼":[["八带鱼是一种生活在深海的鱼类。","سەككىز بەلۋاغلىق بېلىق چوڭقۇر دېڭىزدا ياشايدىغان بىر خىل بېلىقتۇر.","sekkiz belwaghliq béliq chongqur déngizda yashaydighan bir xil béliqtur."]],"公断":[["裁判做出公断，平息了双方的争议。","ھاكىم ئومۇمىي ھۆكۈم چىقىرىپ، ئىككى تەرەپنىڭ تالاش-تارتىشىنى تىندۇردى.","hakim omumiy höküm chiqirip, ikki terepning talash-tartishini tindurdi."]],"公检法":[["公检法协同打击犯罪行为。","ئاممىۋى تەكشۈرۈش، پروكۇراتۇرا ۋە سوت ئورگانلىرى جىنايى قىلمىشلارغا قارشى بىرلىكتە كۈرەش قىلىدۇ.","ammiwi tekshürüsh, prokuratura we sot organliri jinayi qilmishlargha qarshi birlikte küresh qilidu."]],"公民社会":[["公民社会是民主制度的重要组成部分。","پۇقرالىق جەمئىيىتى دېموكراتىيە تۈزۈمىنىڭ مۇھىم تەركىبىي قىسمىدۇر.","puqraliq jem'iyiti démokratiye tüzümining muhim terkibiy qismidur."]],"六库镇":[["六库镇以独特的文化闻名。","ليۇكۇ بازىرى ئۆزگىچە مەدەنىيىتى بىلەن داڭلىق.","lyuku baziri özgiche medeniyiti bilen dangliq."]],"冒名顶替者":[["冒名顶替者最终被揭穿。","يالغان شەخسىيەتچى ئاخىرى ئاشكارىلاندى.","yalghan shexsiyetchi axiri ashkarilandi."]],"出活":[["今天出活效率很高。","بۈگۈن ئىشلەپچىقىرىش ئۈنۈمى ئىنتايىن يۇقىرى.","bügün ishlepchiqirish ünümi intayin yuqiri."]],"出尔反尔":[["他出尔反尔，不守信用。","ئۇ سۆزىدە تۇرماي، ئېغىزىدىن چىققاننى ئىجرا قىلمايدۇ.","u sözide turmay, éghizidin chiqqanni ijra qilmaydu."]],"分升":[["分升是容量单位，常用于实验。","دىسىلىتىر سىغىم بىرلىكى بولۇپ، ئادەتتە تەجرىبىلەردە ئىشلىتىلىدۇ.","disilitir sighim birliki bolup, adette tejribilerde ishlitilidu."]],"分文":[["他分文不取。","ئۇ بىر تىيىن ئالمايدۇ.","u bir tiyin almaydu."]],"冰山":[["冰山漂浮在寒冷的海洋中。","مۇز تاغ سوغۇق دېڭىزدا لەيلەپ يۈرىدۇ.","muz tagh soghuq déngizda leylep yüridu."]],"冰柱":[["屋檐上挂满了冰柱。","ئۆي تۆمۈرىگە مۇز شاملىرى ئېسىلىپ تۇرۇپتۇ.","öy tömürige muz shamliri ésilip turuptu."]],"前置":[["前置摄像头画质清晰。","ئالدىغا ئورۇنلاشتۇرۇلغان كامېرانىڭ سۈرەت سۈپىتى ئېنىق.","aldigha orunlashturulghan kaméraning süret süpiti éniq."]],"制冷":[["空调的制冷效果非常好。","ھاۋا تەڭشىگۈچنىڭ سوۋۇتۇش ئۈنۈمى ئىنتايىن ياخشى.","hawa tengshigüchning sowutush ünümi intayin yaxshi."]],"刷题":[["他每天刷题提高成绩。","ئۇ ھەر كۈنى مەشىق ئىشلەپ نەتىجىسىنى ئۆستۈرىدۇ.","u her küni meshiq ishlep netijisini östüridu."]],"前因后果":[["要弄清前因后果。","ئالدىنقى سەۋەب ۋە ئاقىبەتنى ئېنىقلاپ چىقىش كېرەك.","aldinqi seweb we aqibetni éniqlap chiqish kérek."]],"剧终":[["剧终时观众报以热烈掌声。","تېياتىر ئاخىرلاشقاندا تاماشىبىنلار ئىللىق ئالقىش ياڭراتتى.","téyatir axirlashqanda tamashibinlar illiq alqish yangratti."]],"劈叉":[["她能做劈叉。","ئۇ شالاڭ ئېچىلالايدۇ.","u shalang échilalaydu."]],"剧作家":[["这位剧作家创作了多部经典作品。","بۇ دراما يازغۇچى نۇرغۇن كلاسسىك ئەسەرلەرنى ياراتتى.","bu drama yazghuchi nurghun klassik eserlerni yaratti."]],"刘熙":[["刘熙是中国古代的一位文学家。","لىۇ شى قەدىمكى جۇڭگو دەۋرىدىكى بىر ئەدىب.","liu shi qedimki junggo dewridiki bir edib."]],"副主席":[["副主席对活动安排做了详细说明。","مۇئاۋىن رەئىس پائالىيەت ئورۇنلاشتۇرۇشى ھەققىدە تەپسىلىي چۈشەندۈرۈش بەردى.","muawin reis paaliyet orunlashturushi heqqide tepsiliy chüshendürüsh berdi."]],"加满":[["请把油箱加满。","ماي باكىنى تولۇق قۇيۇڭ.","may bakini toluq quyung."]],"加官进禄":[["他因成就被加官进禄。","ئۇ نەتىجىسى سەۋەبىدىن ئەمەل ۋە مائاشى ئۆستۈرۈلدى.","u netijisi sewebidin emel we maashi östürüldi."]],"勃艮第":[["勃艮第以葡萄酒闻名。","بۇرگۇندى شەرابى بىلەن مەشھۇر.","burgundi sherabi bilen meshhur."]],"加塞儿":[["他试图在队伍中加塞儿。","ئۇ سەپتە ئارىلىق قىستۇرۇشقا ئۇرۇندى.","u septe ariliq qisturushqa urundi."]],"包车":[["我们租了一辆包车去旅行。","بىز ساياھەتكە ئايرىم ئاپتوموبىل ئىجارە ئالدۇق.","biz sayahetke ayrim aptomobil ijare alduq."]],"劝课":[["官员负责劝课农民耕种。","ئەمەلدارلار دېھقانلارنىڭ يەر ئىشلەشىنى نەسىھەت قىلىشقا مەسئۇل.","emeldarlar déhqanlarning yer ishleshini nesihet qilishqa mes'ul."]],"北领地":[["北领地是澳大利亚的一个地区。","شىمالىي زېمىن ئاۋسترالىيەنىڭ بىر رايونى.","shimaliy zémin awstraliyening bir rayoni."]],"南岸":[["长江的南岸风景十分优美。","چاڭجياڭ دەرياسىنىڭ جەنۇبىي قىرغىقىنىڭ مەنزىرىسى ئىنتايىن گۈزەل.","changjyang deryasining jenubiy qirghiqining menzirisi intayin güzel."]],"午安":[["午安，祝您度过愉快的下午。","ياخشى چۈش، سىزگە خۇشال چۈشتىن كېيىنكى ۋاقىتنى تىلەيمەن.","yaxshi chüsh, sizge xushal chüshtin kéyinki waqitni tileymen."]],"午觉":[["午觉时间不宜过长。","چۈشلۈك ئۇخلاش ۋاقتى بەك ئۇزۇن بولماسلىقى كېرەك.","chüshlük uxlash waqti bek uzun bolmasliqi kérek."]],"南陵县":[["南陵县盛产优质大米。","نەنلىڭ ناھىيەسى ئەلا سۈپەتلىك گۈرۈچ ئىشلەپچىقىرىدۇ.","nenling nahiyesi ela süpetlik gürüch ishlepchiqiridu."]],"博望":[["博望是历史名城。","بوۋاڭ تارىخىي داڭلىق شەھەردۇر.","bowang tarixiy dangliq sheherdur."]],"占满":[["仓库已经被货物占满。","ئامبار ماللار بىلەن تولۇپ كەتتى.","ambar mallar bilen tolup ketti."]],"卡森城":[["卡森城位于美国内华达州。","كارسون شەھىرى ئامېرىكىنىڭ نېۋادا شىتاتىدا جايلاشقان.","karson shehiri amérikining néwada shitatida jaylashqan."]],"厚望":[["老师对他寄予厚望。","ئوقۇتقۇچى ئۇنىڭغا زور ئۈمىد باغلىدى.","oqutquchi uninggha zor ümid baghlidi."]],"叉尾太阳鸟":[["叉尾太阳鸟色彩鲜艳。","ئارىلاش قوشۇق قۇيرۇقلۇق كۈنقۇشىنىڭ رەڭگى پارقىراق.","arilash qoshuq quyruqluq künqushining renggi parqiraq."]],"午餐肉":[["午餐肉是西式三明治的常见配料。","چۈشلۈك گۆش غەرب ئۇسلۇبىدىكى ساندۋىچلارنىڭ ئادەتتىكى ماتېرىيالى.","chüshlük gösh gherb uslubidiki sandwichlarning adettiki matériyali."]],"受俸":[["官员受俸以维持生活。","ئەمەلدارلار تۇرمۇشىنى ساقلاپ قېلىش ئۈچۈن ئايلىق ئالىدۇ.","emeldarlar turmushini saqlap qélish üchün ayliq alidu."]],"叫牌":[["他在游戏中叫牌。","ئۇ ئويۇندا كارتا چاقىردى.","u oyunda karta chaqirdi."]],"可数名词":[["可数名词需要加复数。","ساناقلىق ئىسىملارغا كۆپلۈك قوشۇش كېرەك.","sanaqliq isimlargha köplük qoshush kérek."]],"古来":[["古来人们就崇尚自然之美。","قەدىمدىن تارتىپ كىشىلەر تەبىئەت گۈزەللىكىنى ئۇلۇغلىغان.","qedimdin tartip kishiler tebiet güzellikini ulughlighan."]],"吃一堑，长一智":[["吃一堑，长一智，失败是成功之母。","بىر قېتىم ئازار يېتىپ، بىر ئەقىل ئۆگىنىسەن، مەغلۇبىيەت مۇۋەپپەقىيەتنىڭ ئانىسى.","bir qétim azar yétip, bir eqil öginisen, meghlubiyet muweppeqiyetning anisi."]],"吃喝玩乐":[["周末就是吃喝玩乐。","ھەپتە ئاخىرى يېيىش-ئىچىش، ئويناش-كۈلۈش.","hepte axiri yéyish-ichish, oynash-külüsh."]],"吉安乡":[["吉安乡风景优美，适合旅游。","جىئەن يېزىسىنىڭ مەنزىرىسى گۈزەل، ساياھەتكە ماس كېلىدۇ.","jien yézisining menzirisi güzel, sayahetke mas kélidu."]],"吉普车":[["吉普车深受户外爱好者的喜爱。","جىپ چەككۈچىنى سىرتقى پائالىيەت ھەۋەسكارلىرى ئىنتايىن ياخشى كۆرىدۇ.","jip chekküchini sirtqi paaliyet heweskarliri intayin yaxshi köridu."]],"吞食":[["狼吞食猎物时毫不留情。","بۆرە ئولجىسىنى يۇتۇۋاتقاندا رەھىمسىزلىك قىلمايدۇ.","böre oljisini yutuwatqanda rehimsizlik qilmaydu."]],"名义价值":[["这个物品的名义价值很高。","بۇ بۇيۇمنىڭ نامى قىممىتى بەك يۇقىرى.","bu buyumning nami qimmiti bek yuqiri."]],"吹牛拍马":[["他整天吹牛拍马，讨人欢心。","ئۇ كۈن بويى ماختاپ، يېلىپ، كىشىلەرنىڭ كۆڭلىنى ئېلىشقا تىرىشىدۇ.","u kün boyi maxtap, yélip, kishilerning könglini élishqa tirishidu."]],"哈拉":[["哈拉是蒙古的姓氏。","خارا موڭغۇلىيەنىڭ بىر فامىلىسىدۇر.","xara mongghuliyening bir familisidur."]],"哈吉":[["哈吉是伊斯兰教的重要仪式。","ھەج ئىسلام دىنىنىڭ مۇھىم رەسمىيىتى.","hej islam dinining muhim resmiyiti."]],"含沙量":[["河沙的含沙量直接影响流速。","دەريا قۇمىنىڭ قۇم تەركىبى ئاقىم تېزلىكىگە بىۋاسىتە تەسىر كۆرسىتىدۇ.","derya qumining qum terkibi aqim tézlikige biwasite tesir körsitidu."]],"哥伦比亚广播公司":[["哥伦比亚广播公司历史悠久。","كولۇمبىيە رادىيو شىركىتى ئۇزۇن تارىخقا ئىگە.","kolumbiye radiyo shirkiti uzun tarixqa ige."]],"品客":[["他是一位注重品味的现代品客。","ئۇ زەۋقىغا ئەھمىيەت بېرىدىغان زامانىۋى بىر زەۋقلىق ئادەم.","u zewqigha ehmiyet béridighan zamaniwi bir zewqliq adem."]],"唐武宗":[["唐武宗在位期间推行多项改革。","تاڭ ۋۇزۇڭ تەختتە ئولتۇرغان مەزگىلدە نۇرغۇن ئىسلاھاتلارنى ئېلىپ باردى.","tang wuzung textte olturghan mezgilde nurghun islahatlarni élip bardi."]],"品红":[["品红是印刷中常用的颜色之一。","فۇكسىن قىزىل رەڭ بېسىم ئىشلىرىدا كۆپ ئىشلىتىلىدىغان رەڭلەرنىڭ بىرى.","fuksin qizil reng bésim ishlirida köp ishlitilidighan renglerning biri."]],"唐山市":[["唐山市是河北省的工业重镇。","تاڭشەن شەھىرى خېبېي ئۆلكىسىنىڭ سانائەت مەركىزى.","tangshen shehiri xébéy ölkisining sanaet merkizi."]],"唯恐":[["他唯恐事情会出错。","ئۇ پەقەت ئىش خاتا بولۇپ قېلىشىدىن قورقىدۇ.","u peqet ish xata bolup qélishidin qorqidu."]],"叹为观止":[["这场表演让我叹为观止。","بۇ نومۇر ماڭا ھەيران قالارلىق تەسىر بەردى.","bu nomur manga heyran qalarliq tesir berdi."]],"噶当派":[["噶当派是藏传佛教的重要派别。","گادام مازھىبى تىبەت بۇددا دىنىنىڭ مۇھىم مەزھەبلىرىدىن بىرى.","gadam mazhibi tibet budda dinining muhim mezhebliridin biri."]],"嘲哳":[["他的歌声听起来十分嘲哳。","ئۇنىڭ ناخشا ئاۋازى بەك چىقىرلاپ ئاڭلىنىدۇ.","uning naxsha awazi bek chiqirlap anglinidu."]],"噎住":[["他吃饭时不小心噎住了。","ئۇ تاماق يېگەندە سەۋەنسىزلىكتىن بوغۇلۇپ قالدى.","u tamaq yégende sewensizliktin boghulup qaldi."]],"四子王旗":[["四子王旗是内蒙古的一个自治旗。","سىزىۋاڭ چىچى ئىچكى موڭغۇلنىڭ بىر ئاپتونوم چىچىسىدۇر.","siziwang chichi ichki mongghulning bir aptonom chichisidur."]],"四川大学":[["四川大学是中国一所重点大学。","سىچۈەن ئۇنىۋېرسىتېتى جۇڭگونىڭ بىر مۇھىم ئۇنىۋېرسىتېتىدۇر.","sichüen uniwérsitéti junggoning bir muhim uniwérsitétidur."]],"四川旋木雀":[["四川旋木雀是一种小型鸟类。","سىچۈەن ياغاچچى قۇشى كىچىك تىپتىكى بىر قۇشتۇر.","sichüen yaghachchi qushi kichik tiptiki bir qushtur."]],"四角号码":[["四角号码是一种汉字编码方式。","تۆت بۇلۇڭ نومۇرى خەنزۇچە ھەرپلەرنى كودلاش ئۇسۇلىدۇر.","töt bulung nomuri xenzuche herplerni kodlash usulidur."]],"圈粉":[["他通过作品成功圈粉无数。","ئۇ ئەسەرلىرى ئارقىلىق مۇۋەپپەقىيەتلىك ھالدا نۇرغۇن مەستانىلەرنى توپلىدى.","u eserliri arqiliq muweppeqiyetlik halda nurghun mestanilerni toplidi."]],"国营企业":[["国营企业承担社会责任。","دۆلەت كارخانىلىرى جەمئىيەت مەسئۇلىيىتىنى ئۈستىگە ئالىدۇ.","dölet karxaniliri jem'iyet mes'uliyitini üstige alidu."]],"固形物":[["固形物在物理实验中常见。","مۇقىم شەكىللىك ماددا فىزىكا تەجرىبىلىرىدە كۆپ ئۇچرايدۇ.","muqim shekillik madda fizika tejribiliride köp uchraydu."]],"围堵":[["警方对逃犯进行了严密围堵。","ساقچىلار قاچقۇن جىنايەتچىنى قاتتىق قورشىۋالدى.","saqchilar qachqun jinayetchini qattiq qorshiwaldi."]],"围护结构":[["围护结构是建筑的重要组成部分。","قورشاش قۇرۇلمىسى بىنانىڭ مۇھىم تەركىبىي قىسمىدۇر.","qorshash qurulmisi binaning muhim terkibiy qismidur."]],"土卫六":[["土卫六拥有浓厚的大气层和甲烷湖泊。","توپا ھەمراھى ئالتىدا قويۇق ئاتموسفېرا ۋە مېتان كۆللىرى بار.","topa hemrahi altida qoyuq atmosféra we métan kölliri bar."]],"土地改革":[["土地改革改变了农村的经济结构。","يەر ئىسلاھاتى يېزا ئىقتىساد قۇرۇلمىسىنى ئۆزگەرتتى.","yer islahati yéza iqtisad qurulmisini özgertti."]],"地钱":[["地钱是古代对土地税的俗称。","يەر پۇلى قەدىمدە يەر بېجىگە بېرىلگەن ئاتالغۇ.","yer puli qedimde yer béjige bérilgen atalghu."]],"均质":[["材料需保持均质。","ماتېرىيال تەكشى سۈپەتنى ساقلىشى كېرەك.","matériyal tekshi süpetni saqlishi kérek."]],"坐台小姐":[["坐台小姐服务很周到。","ئولتۇرۇش مۇلازىمەتچى قىزنىڭ مۇلازىمىتى ناھايىتى ئىنچىكە ئىدى.","olturush mulazimetchi qizning mulazimiti nahayiti inchike idi."]],"坎塔布连":[["坎塔布连地区以葡萄酒闻名。","كانتابرىيە رايونى ئۈزۈم شارابى بىلەن داڭلىق.","kantabriye rayoni üzüm sharabi bilen dangliq."]],"地热电站":[["地热电站的运营成本较低。","گېئوتېرمىك ئېلېكتر ئىستانسىسىنىڭ يۈرگۈزۈش چىقىمى بىر قەدەر تۆۋەن.","géotérmik éléktr istansisining yürgüzüsh chiqimi bir qeder töwen."]],"培亚":[["培亚是当地著名的教育家。","پەييا يەرلىكتە تونۇلغان مەشھۇر مائارىپچى.","peyya yerlikte tonulghan meshhur maaripchi."]],"基因座":[["基因座是基因在染色体上的特定位置。","گېن ئورنى گېننىڭ خروموسومدىكى مۇئەييەن ئورنى.","gén orni génning xromosomdiki mueyyen orni."]],"塔夫绸":[["塔夫绸是一种高档的丝绸面料。","تاففېتا يۇقىرى سۈپەتلىك يىپەك رەختتۇر.","tafféta yuqiri süpetlik yipek rexttur."]],"墓穴":[["墓穴深藏于山腹之中。","قەبرە ئۆڭكۈرى تاغ قارنىغا چوڭقۇر يوشۇرۇنغان.","qebre öngküri tagh qarnigha chongqur yoshurunghan."]],"壁厢":[["壁厢里摆放着许多老物件。","دىوار يان تەرەپتە نۇرغۇن كونا بۇيۇملار قويۇلغان.","dioar yan terepte nurghun kona buyumlar qoyulghan."]],"坠胡":[["坠胡是一种传统民族乐器。","زۇيخۇ ئەنئەنىۋى مىللىي چالغۇ ئەسۋابىدۇر.","zuyxu en'eniwi milliy chalghu eswabidur."]],"报分":[["请准确报分给裁判。","ھاكىمغا نومۇرنى توغرا مەلۇم قىلىڭ.","hakimgha nomurni toghra melum qiling."]],"报告书":[["报告书已经提交给上级。","دوكلاتنامە يۇقىرى دەرىجىلىك ئورۇنغا تاپشۇرۇلدى.","doklatname yuqiri derijilik orungha tapshuruldi."]],"夏王朝":[["夏王朝是中国最早的王朝之一。","شىيا سۇلالىسى جۇڭگونىڭ ئەڭ بۇرۇنقى سۇلالىلىرىنىڭ بىرى.","shiya sulalisi junggoning eng burunqi sulalilirining biri."]],"外商独资企业":[["这家是外商独资企业。","بۇ سىرتقى سودىگەرلەر ئالاھىدە مۈلۈكچىلىك قىلىدىغان كارخانا.","bu sirtqi sodigerler alahide mülükchilik qilidighan karxana."]],"夙夜匪懈":[["团队夙夜匪懈，终于完成任务。","گۇرۇپپا ئەتىگەندىن كەچكىچە بوشاشماي، ئاخىرى ۋەزىپىنى تاماملىدى.","guruppa etigendin kechkiche boshashmay, axiri wezipini tamamlidi."]],"夙诺":[["他始终遵守自己的夙诺。","ئۇ ھەمىشە ئۆزىنىڭ كونا ۋەدىسىگە ئەمەل قىلىدۇ.","u hemishe özining kona wedisige emel qilidu."]],"多佛":[["多佛是一位音乐家。","دوفېر بىر مۇزىكانت.","dofér bir muzikant."]],"大山猫":[["大山猫是森林的霸主。","چوڭ تاغ مۈشۈكى ئورماننىڭ ھۆكۈمرانى.","chong tagh müshüki ormanning hökümrani."]],"外蒙古":[["外蒙古以广阔的草原和独特的游牧文化闻名。","تاشقى موڭغۇلىيە كەڭ يايلاق ۋە ئۆزگىچە كۆچمەن چارۋىچىلىق مەدەنىيىتى بىلەن داڭلىق.","tashqi mongghuliye keng yaylaq we özgiche köchmen charwichiliq medeniyiti bilen dangliq."]],"大洋中脊":[["大洋中脊是海底的重要构造。","چوڭ ئوكيان ئوتتۇرا تاغ تىزمىسى دېڭىز ئاستىدىكى مۇھىم قۇرۇلما.","chong okyan ottura tagh tizmisi déngiz astidiki muhim qurulma."]],"大乌鸦":[["大乌鸦的叫声在森林中格外响亮。","چوڭ قاغىنىڭ ئاۋازى ئورماندا ئالاھىدە ياڭرايدۇ.","chong qaghining awazi ormanda alahide yangraydu."]],"大规模杀伤性武器":[["大规模杀伤性武器很危险。","كەڭ كۆلەملىك قىرغىنچىلىق قوراللىرى ئىنتايىن خەتەرلىكتۇر.","keng kölemlik qirghinchiliq qoralliri intayin xeterliktur."]],"大萧条":[["大萧条时期，经济严重衰退。","بۈيۈك چېكىنىش دەۋرىدە ئىقتىساد ئېغىر تەرەققىياتسىزلىققا ئۇچرىدى.","büyük chékinish dewride iqtisad éghir tereqqiyatsizliqqa uchridi."]],"天方夜谭":[["这个故事简直是天方夜谭。","بۇ ھېكايە خۇددى «تەڭرىپەن يېقىن كېچە» دېگەندەكلا.","bu hékaye xuddi «tengripen yéqin kéche» dégendekla."]],"大谈":[["他大谈自己的观点。","ئۇ ئۆزىنىڭ كۆز قارىشى توغرىسىدا چوڭ گەپ قىلدى.","u özining köz qarishi toghrisida chong gep qildi."]],"天渊":[["天渊比喻极大的差异。","تيەنيۈەن ئىنتايىن چوڭ پەرقنى تەمسىل قىلىدۇ.","tyenyüen intayin chong perqni temsil qilidu."]],"奉陪":[["我奉陪您一起参观这座博物馆。","مەن سىز بىلەن بىرگە بۇ مۇزېينى زىيارەت قىلىمەن.","men siz bilen birge bu muzéyni ziyaret qilimen."]],"天镇县":[["天镇县位于山西省北部。","تەڭرى بازىرى ناھىيىسى شەنشى ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","tengri baziri nahiyisi shenshi ölkisining shimalida jaylashqan."]],"奎屯市":[["奎屯市以石油工业闻名全国。","كۈيتۈن شەھىرى نېفىت سانائىتى بىلەن پۈتۈن مەملىكەتكە مەشھۇر.","küytün shehiri néfit sanaiti bilen pütün memliketke meshhur."]],"奥康纳":[["奥康纳是著名的哲学家。","ئوكونور مەشھۇر پەيلاسوپ.","okonor meshhur peylasop."]],"奶制品":[["奶制品包括牛奶、奶酪和酸奶。","سۈت مەھسۇلاتلىرى سۈت، پىشلاق ۋە قاتىقنى ئۆز ئىچىگە ئالىدۇ.","süt mehsulatliri süt, pishlaq we qatiqni öz ichige alidu."]],"奥利奥":[["他喜欢吃奥利奥饼干。","ئۇ ئورېئو پېچىنە يېيىشنى ياخشى كۆرىدۇ.","u oréo péchine yéyishni yaxshi köridu."]],"姆指":[["姆指受伤会影响打字。","باش بارماق يارىلانسا، خەت بېسىشقا تەسىر يېتىدۇ.","bash barmaq yarilansa, xet bésishqa tesir yétidu."]],"娟秀":[["她长得娟秀。","ئۇ چىرايلىق ۋە نەپىس.","u chirayliq we nepis."]],"威基基":[["威基基海滩风景优美。","ۋايكىكىي قىرغىقىنىڭ مەنزىرىسى ئىنتايىن گۈزەل.","waykikiy qirghiqining menzirisi intayin güzel."]],"婆罗洲":[["婆罗洲是世界第三大岛。","بورنىئو دۇنيادىكى ئۈچىنچى چوڭ ئارال.","bornio dunyadiki üchinchi chong aral."]],"字典":[["这本字典收录了数千个汉字。","بۇ لۇغەتتە مىڭلىغان خەنزۇ يېزىقى خاتىرىلەنگەن.","bu lughette minglighan xenzu yéziqi xatirilengen."]],"子民":[["子民指君主统治下的臣民。","خەلق پادىشاھ ھۆكۈمرانلىقى ئاستىدىكى تەبەئەلەرنى كۆرسىتىدۇ.","xelq padishah hökümranliqi astidiki tebeelerni körsitidu."]],"嫡堂":[["嫡堂在家族中地位显赫。","قانۇنىي ئاكا-ئۇكا جەمەتتە ئالاھىدە ئورۇنغا ئىگە.","qanuniy aka-uka jemette alahide orungha ige."]],"宋美龄":[["宋美龄是蒋介石的妻子，政治人物。","سۇڭ مېيلىڭ چياڭ جيېشىنىڭ ئايالى، سىياسىي شەخس.","sung méyling chyang jyéshining ayali, siyasiy shexs."]],"宣泄":[["他通过运动宣泄压力。","ئۇ تەنتەربىيە ئارقىلىق بېسىمنى چىقىرىدۇ.","u tenterbiye arqiliq bésimni chiqiridu."]],"宣传攻势":[["品牌发起了一场大规模的宣传攻势。","ماركا كەڭ كۆلەملىك تەشۋىقات ھۇجۇمىنى قوزغىدى.","marka keng kölemlik teshwiqat hujumini qozghidi."]],"定性理论":[["定性理论为研究提供了框架。","سۈپەت نەزەرىيىسى تەتقىقاتقا رامكا بىلەن تەمىنلەيدۇ.","süpet nezeriyisi tetqiqatqa ramka bilen teminleydu."]],"宜都市":[["宜都市是宜昌市下属的市。","يىدۇ شەھىرى يىچاڭ شەھىرىگە قاراشلىق شەھەر.","yidu shehiri yichang shehirige qarashliq sheher."]],"密文":[["密文需要经过解密才能阅读。","شىفىرلانغان تېكىستنى ئوقۇش ئۈچۈن شىفىردىن يېشىش كېرەك.","shifirlanghan tékistni oqush üchün shifirdin yéshish kérek."]],"家爷":[["家爷是家中最年长的男性长辈，备受尊敬。","بوۋام ئائىلىدىكى ئەڭ ياشانغان ئەر ئاقساقال بولۇپ، ئىنتايىن ھۆرمەتكە سازاۋەر.","bowam ailidiki eng yashanghan er aqsaqal bolup, intayin hörmetke sazawer."]],"家眷":[["家眷包括家庭成员中的亲属和配偶。","ئائىلە ئەزالىرى ئائىلە ئەزالىرى ئىچىدىكى تۇغقانلار ۋە جۆرەلەرنى ئۆز ئىچىگە ئالىدۇ.","aile ezaliri aile ezaliri ichidiki tughqanlar we jörelerni öz ichige alidu."]],"寥寥可数":[["成功者寥寥可数。","مۇۋەپپەقىيەت قازانغۇچىلارنى بارماق بىلەن سانغىلى بولىدۇ.","muweppeqiyet qazanghuchilarni barmaq bilen sanghili bolidu."]],"密织":[["工匠们用密织工艺制作丝绸。","ھۈنەرۋەنلەر زىچ توقۇش تېخنىكىسى بىلەن يىپەك توقۇيدۇ.","hünerwenler zich toqush téxnikisi bilen yipek toquydu."]],"密度计":[["实验室使用密度计测量液体密度。","تەجرىبىخانا زىچلىق ئۆلچىگۈچ ئارقىلىق سۇيۇقلۇقنىڭ زىچلىقىنى ئۆلچەيدۇ.","tejribixana zichliq ölchigüch arqiliq suyuqluqning zichliqini ölcheydu."]],"宁波":[["宁波是中国东部的重要港口。","نىڭبو جۇڭگونىڭ شەرقىدىكى مۇھىم پورت.","ningbo junggoning sherqidiki muhim port."]],"宠信":[["他备受君主的宠信。","ئۇ پادىشاھنىڭ ئىشەنچىسىگە ئېرىشكەن.","u padishahning ishenchisige érishken."]],"对讲机":[["使用对讲机可以远距离通话。","رادىئو ئالاقە ئۈسكۈنىسى ئارقىلىق يىراق مۇساپىدىن سۆزلىشىشكە بولىدۇ.","radio alaqe üskünisi arqiliq yiraq musapidin sözlishishke bolidu."]],"小儿科":[["医院的小儿科很忙。","دوختۇرخانىنىڭ كىچىك بالىلار بۆلۈمى بەك ئالدىراش.","doxturxanining kichik balilar bölümi bek aldirash."]],"小数":[["计算时，要注意小数的位数。","ھېسابلاش ۋاقتىدا ئونلۇق كەسىرنىڭ ئورنىغا دىققەت قىلىش كېرەك.","hésablash waqtida onluq kesirning ornigha diqqet qilish kérek."]],"尼哥底母":[["尼哥底母是《圣经》中的人物。","نىكودېمۇس ئىنجىلدىكى بىر شەخستۇر.","nikodémus injildiki bir shexstur."]],"尼散月":[["尼散月是犹太历的第一个月。","نىسان ئاي يەھۇدىي كالېندارىنىڭ بىرىنچى ئېيىدۇر.","nisan ay yehudiy kaléndarining birinchi éyidur."]],"尿素":[["尿素是化肥的重要成分。","ئۇرېيا ئوغۇتلارنىڭ مۇھىم تەركىبىي قىسمىدۇر.","uréya oghutlarning muhim terkibiy qismidur."]],"屎意":[["他感到强烈的屎意，急忙去厕所。","ئۇ كۈچلۈك تەرەت قىلىش ئېھتىياجىنى ھېس قىلىپ، ئالدىراپ ھاجەتخانىغا كەتتى.","u küchlük teret qilish éhtiyajini hés qilip, aldirap hajetxanigha ketti."]],"尾矿":[["尾矿需要妥善处理以防污染。","قۇيرۇق مىنېرالنى مۇۋاپىق بىر تەرەپ قىلىپ، بۇلغىنىشتىن ساقلىنىش كېرەك.","quyruq minéralni muwapiq bir terep qilip, bulghinishtin saqlinish kérek."]],"屯子":[["那个小屯子坐落在山脚下，宁静而美丽。","ئۇ كىچىك تۇن يېزىسى تاغ ئېتىكىدە جايلاشقان بولۇپ، تىنچ ۋە گۈزەل.","u kichik tun yézisi tagh étikide jaylashqan bolup, tinch we güzel."]],"岸边":[["小船停靠在岸边。","كىچىك كېمە قىرغاق بويىغا توختىدى.","kichik kéme qirghaq boyigha toxtidi."]],"峇峇娘惹":[["峇峇娘惹文化独特。","بالىبالى مەدەنىيىتى ئۆزگىچە.","balibali medeniyiti özgiche."]],"岩床":[["岩床是地质学家研究的重要对象。","تاش قاتلام گېئولوگلار ئۈچۈن مۇھىم تەتقىقات ئوبيېكتى.","tash qatlam géologlar üchün muhim tetqiqat obyékti."]],"山鹪莺":[["山鹪莺的歌声婉转，常在山林间传唱。","تاغ چىمچىقىنىڭ ناخشىسى يېقىملىق، دائىم تاغ-ئورمانلاردا ئېيتىلىدۇ.","tagh chimchiqining naxshisi yéqimliq, daim tagh-ormanlarda éytilidu."]],"岩羊":[["岩羊生活在高山岩石地带。","تاش ئۆچكەسى ئېگىز تاغلارنىڭ تاشلىق رايونلىرىدا ياشايدۇ.","tash öchkesi égiz taghlarning tashliq rayonlirida yashaydu."]],"工分":[["工分是劳动的计量单位。","ئىش نومۇرى ئەمگەكنى ئۆلچەش بىرلىكىدۇر.","ish nomuri emgekni ölchesh birlikidur."]],"左箭头键":[["键盘上的左箭头键。","كۇنۇپكا تاختىسىدىكى سول ياچاق كۇنۇپكىسى.","kunupka taxtisidiki sol yachaq kunupkisi."]],"左顾右盼":[["他左顾右盼，显得十分紧张。","ئۇ سولغا-ئوڭغا قاراپ، ئىنتايىن جىددىيلەشكەن كۆرۈندى.","u solgha-onggha qarap, intayin jiddiyleshken köründi."]],"巧合":[["真是巧合，我们竟然相遇了。","ھەقىقەتەن تاسادىپىيلىك بولدى، بىز ئۇچرىشىپ قالدۇق.","heqiqeten tasadipiylik boldi, biz uchriship qalduq."]],"巧诈":[["巧诈往往难以长久。","ماھىرانە ئالدامچىلىق ئادەتتە ئۇزۇنغا بارالمايدۇ.","mahirane aldamchiliq adette uzungha baralmaydu."]],"布松布拉":[["布松布拉是一种传统的舞蹈形式。","بۇسۇنبرا ئەنئەنىۋى ئۇسسۇل شەكلىدۇر.","busunbra en'eniwi ussul sheklidur."]],"巴拿芬":[["巴拿芬是法国的一座城市。","بالانفېن فرانسىيەنىڭ بىر شەھىرى.","balanfén fransiyening bir shehiri."]],"巴拿马":[["巴拿马是中美洲的一个国家。","پاناما ئوتتۇرا ئامېرىكىدىكى بىر دۆلەت.","panama ottura amérikidiki bir dölet."]],"帕台农":[["帕台农是古希腊的著名建筑。","پارتېنون قەدىمكى گرېتسىيەدىكى داڭلىق بىر بىنا ئىدى.","parténon qedimki grétsiyediki dangliq bir bina idi."]],"布达佩斯":[["布达佩斯是匈牙利的首都。","بۇداپېشت ۋېنگىرىيەنىڭ پايتەختىدۇر.","budapésht wéngiriyening paytextidur."]],"平均剂量":[["药物需按平均剂量服用。","دورا ئوتتۇرىچە مىقدار بويىچە ئىچىلىشى كېرەك.","dora otturiche miqdar boyiche ichilishi kérek."]],"床笫之事":[["夫妻间床笫之事很私密。","ئەر-خوتۇن ئارىسىدىكى كارۋات-تۆشەك ئىشلىرى ئىنتايىن شەخسىي.","er-xotun arisidiki karwat-töshek ishliri intayin shexsiy."]],"序数":[["序数需要确认。","تەرتىپ سانىنى جەزملەشتۈرۈش كېرەك.","tertip sanini jezmleshtürüsh kérek."]],"帝喾":[["帝喾是中国上古时期的帝王。","دىكۇ جۇڭگونىڭ قەدىمكى دەۋرىدىكى ئىمپېراتورىدۇر.","diku junggoning qedimki dewridiki impératoridur."]],"床友":[["他们是多年的床友。","ئۇلار كۆپ يىللىق كارۋاتداشلار.","ular köp yilliq karwatdashlar."]],"广传":[["消息迅速广传至各地。","خەۋەر تېز سۈرئەتتە ھەر جايلارغا كەڭ تارقالدى.","xewer téz sür'ette her jaylargha keng tarqaldi."]],"广漠":[["广漠的天空令人感到宁静。","كەڭرى ئاسمان كىشىگە خاتىرجەملىك بېغىشلايدۇ.","kengri asman kishige xatirjemlik béghishlaydu."]],"广告牌":[["广告牌矗立在高速公路旁。","ئېلان تاختىسى تېز سۈرئەتلىك تاشيول بويىدا تىكلەنگەن.","élan taxtisi téz sür'etlik tashyol boyida tiklengen."]],"广州中医药大学":[["广州中医药大学是华南著名的医学院校。","گۇاڭجۇ جۇڭيى دورىگەرلىك ئۇنىۋېرسىتېتى جەنۇبىي جۇڭگونىڭ مەشھۇر تېببىي مەكتىپىدۇر.","guangju jungyi dorigerlik uniwérsitéti jenubiy junggoning meshhur tébbiy mektipidur."]],"强攻":[["军队发起强攻，突破防线。","ئارمىيە كۈچلۈك ھۇجۇم قوزغاپ، مۇداپىئە لىنىيىسىنى بۆسۈپ ئۆتتى.","armiye küchlük hujum qozghap, mudapie liniyisini bösüp ötti."]],"张怡":[["张怡在绘画领域取得了显著成就。","جاڭ يى رەسىم ساھەسىدە كۆرۈنەرلىك نەتىجىلەرگە ئېرىشتى.","jang yi resim saheside körünerlik netijilerge érishti."]],"张爱玲":[["张爱玲是中国现代文学的重要作家。","جاڭ ئەيلىڭ جۇڭگو زامانىۋى ئەدەبىياتىنىڭ مۇھىم يازغۇچىسى.","jang eyling junggo zamaniwi edebiyatining muhim yazghuchisi."]],"张衡":[["张衡发明了浑天仪。","جاڭ خېڭ ھۈنتيەن ئەسۋابىنى كەشىپ قىلدى.","jang xéng hüntyen eswabini keship qildi."]],"后魏":[["后魏是中国历史上的一个政权。","ئاخىرقى ۋېي جۇڭگو تارىخىدىكى بىر ھاكىمىيەتتۇر.","axirqi wéy junggo tarixidiki bir hakimiyettur."]],"后摇滚":[["后摇滚融合了多种音乐风格，独具特色。","ئاخىرقى روك كۆپ خىل مۇزىكا ئۇسلۇبلىرىنى بىرلەشتۈرۈپ، ئۆزگىچە ئالاھىدىلىككە ئىگە.","axirqi rok köp xil muzika uslublirini birleshtürüp, özgiche alahidilikke ige."]],"微软":[["微软推出了最新的操作系统。","مىكروسوفت ئەڭ يېڭى مەشغۇلات سىستېمىسىنى تەقدىم قىلدى.","mikrosoft eng yéngi meshghulat sistémisini teqdim qildi."]],"忠信":[["他为人忠信，值得信赖。","ئۇ سادىق ۋە ئىشەنچلىك، ئىشەنگىلى بولىدۇ.","u sadiq we ishenchlik, ishengili bolidu."]],"心室":[["医生检查发现他的心室功能异常。","دوختۇر تەكشۈرۈپ ئۇنىڭ يۈرەك قېرىنچىسىنىڭ ئىقتىدارى نورمالسىزلىقىنى بايقىدى.","doxtur tekshürüp uning yürek qérinchisining iqtidari normalsizliqini bayqidi."]],"性侵犯":[["性侵犯应受法律制裁。","جىنسىي تاجاۋۇز قانۇن جازاسىغا تارتىلىشى كېرەك.","jinsiy tajawuz qanun jazasigha tartilishi kérek."]],"彻夜":[["他彻夜未眠，思考人生。","ئۇ پۈتۈن كېچە ئۇخلىمىدى، ھاياتنى ئويلاندى.","u pütün kéche uxlimidi, hayatni oylandi."]],"徽州":[["徽州历史悠久，风景优美。","خۇيجۇ ئۇزۇن تارىخقا ئىگە، مەنزىرىسى گۈزەل.","xuyju uzun tarixqa ige, menzirisi güzel."]],"恐怖片":[["这部恐怖片令人毛骨悚然。","بۇ قورقۇنچلۇق فىلىم كىشىنىڭ يۈرىكىنى قاقشىتىدۇ.","bu qorqunchluq filim kishining yürikini qaqshitidu."]],"恐怖症":[["他患有严重的恐怖症。","ئۇ ئېغىر قورقۇنچلۇق كېسەلگە گىرىپتار بولغان.","u éghir qorqunchluq késelge giriptar bolghan."]],"怯子":[["这个怯子总是躲在角落不敢说话。","بۇ تارتىنچاق بالا ھەمىشە بۇلۇڭدا يوشۇرۇنۇپ، سۆزلەشكە پېتىنالمايدۇ.","bu tartinchaq bala hemishe bulungda yoshurunup, sözleshke pétinalmaydu."]],"恩格尔":[["恩格尔提出了著名的恩格尔定律。","ئېنگېل داڭلىق ئېنگېل قانۇنىنى ئوتتۇرىغا قويدى.","éngél dangliq éngél qanunini otturigha qoydi."]],"心理统计学":[["心理统计学结合统计方法分析心理数据。","پسىخولوگىيەلىك ستاتىستىكا ستاتىستىكىلىق ئۇسۇللارنى بىرلەشتۈرۈپ پسىخولوگىيەلىك سانلىق مەلۇماتلارنى تەھلىل قىلىدۇ.","psixologiyelik statistika statistikiliq usullarni birleshtürüp psixologiyelik sanliq melumatlarni tehlil qilidu."]],"患处":[["医生检查了他的患处。","دوختۇر ئۇنىڭ كېسەل جايىنى تەكشۈردى.","doxtur uning késel jayini tekshürdi."]],"恭城":[["恭城是湖南的一个著名旅游地。","گۇڭچېڭ خۇنەندىكى مەشھۇر ساياھەت جايى.","gungchéng xunendiki meshhur sayahet jayi."]],"恶德":[["这种恶德行为令人不齿。","بۇنداق يامان ئەخلاقسىزلىق كىشىنى يىرگىنىشكە سەۋەب بولىدۇ.","bundaq yaman exlaqsizliq kishini yirginishke seweb bolidu."]],"愕然":[["他听到消息后愕然不已。","ئۇ خەۋەرنى ئاڭلاپ ھەيران قاتتى.","u xewerni anglap heyran qatti."]],"惕然":[["他听到消息后惕然一惊。","ئۇ خەۋەرنى ئاڭلىغاندىن كېيىن تەسكىنلىنىپ، بىر ئەندىشىگە چۆمدى.","u xewerni anglighandin kéyin teskinlinip, bir endishige chömdi."]],"悟净":[["悟净是《西游记》中的角色。","ۋۇجىڭ «غەربكە سەپەر» دىكى بىر رول.","wujing «gherbke seper» diki bir rol."]],"意外事故":[["这起意外事故导致多人受伤。","بۇ تاسادىپىي ھادىسە نۇرغۇن كىشىلەرنىڭ يارىلىنىشىغا سەۋەب بولدى.","bu tasadipiy hadise nurghun kishilerning yarilinishigha seweb boldi."]],"悬雍垂":[["悬雍垂位于口腔后部，对发音有重要作用。","كىچىك تىل ئېغىز بوشلۇقىنىڭ ئارقا قىسمىدا جايلاشقان بولۇپ، تەلەپپۇزغا مۇھىم رول ئوينايدۇ.","kichik til éghiz boshluqining arqa qismida jaylashqan bolup, teleppuzgha muhim rol oynaydu."]],"戏称":[["他常被朋友们戏称为“戏精”。","ئۇ دائىم دوستلىرى تەرىپىدىن «ئويۇنچى» دەپ مازاق قىلىنىدۇ.","u daim dostliri teripidin «oyunchi» dep mazaq qilinidu."]],"应聘者":[["应聘者需提交简历和推荐信进行申请。","ئىمتىھان بەرگۈچىلەر ئىلتىماس قىلىش ئۈچۈن تەرجىمىھال ۋە تەۋسىيە خېتىنى تاپشۇرۇشى كېرەك.","imtihan bergüchiler iltimas qilish üchün terjimihal we tewsiye xétini tapshurushi kérek."]],"应试":[["他专注于应试技巧，成绩显著提升。","ئۇ ئىمتىھان تېخنىكىسىغا دىققەت قىلىپ، نەتىجىسى كۆرۈنەرلىك يۇقىرى كۆتۈرۈلدى.","u imtihan téxnikisigha diqqet qilip, netijisi körünerlik yuqiri kötürüldi."]],"所见":[["他所说的所见与事实相符。","ئۇنىڭ كۆرگەنلىرى پاكىتقا ئۇيغۇن كېلىدۇ.","uning körgenliri pakitqa uyghun kélidu."]],"扇动":[["他扇动翅膀飞上了天空。","ئۇ قاناتلىرىنى قاققىلاپ ئاسمانغا ئۇچتى.","u qanatlirini qaqqilap asmangha uchti."]],"手牵手":[["他们手牵手走在路上。","ئۇلار قول تۇتۇشۇپ يولدا ماڭدى.","ular qol tutushup yolda mangdi."]],"才疏学浅":[["我不过是才疏学浅之人，不敢多言。","مەن پەقەت بىلىمى تەكشە، ئاز سۆزلەشكە جۈرئەت قىلمايدىغان بىر كىشى.","men peqet bilimi tekshe, az sözleshke jür'et qilmaydighan bir kishi."]],"打嘴":[["他打嘴的动作很轻。","ئۇنىڭ ئاغزىنى ئۇرۇش ھەرىكىتى بەك يېنىك.","uning aghzini urush herikiti bek yénik."]],"扎住":[["他用力扎住帐篷的绳索。","ئۇ چېدىرنىڭ ئارقانلىرىنى كۈچ بىلەن چىڭىتتى.","u chédirning arqanlirini küch bilen chingitti."]],"把立":[["雕像的把立设计十分巧妙。","ھەيكەلنىڭ تۇتقۇچ لايىھەسى ئىنتايىن ماھىرلىك بىلەن ئىشلەنگەن.","heykelning tutquch layihesi intayin mahirlik bilen ishlengen."]],"抓猴":[["表演者抓猴很精彩。","ئويۇنچىنىڭ مايمۇن تۇتۇشى ئىنتايىن ئېسىل.","oyunchining maymun tutushi intayin ésil."]],"抗抗生素":[["滥用抗抗生素会导致耐药性。","ئانتىبىئوتىكلارنى سۇيىئىستېمال قىلىش دورا قارشىلىقىنى كەلتۈرۈپ چىقىرىدۇ.","antibiotiklarni suyiistémal qilish dora qarshiliqini keltürüp chiqiridu."]],"拉大便":[["孩子该拉大便了。","بالىنىڭ تەرەت قىلىدىغان ۋاقتى بولدى.","balining teret qilidighan waqti boldi."]],"投放市场":[["新产品已投放市场。","يېڭى مەھسۇلات بازارغا سېلىندى.","yéngi mehsulat bazargha sélindi."]],"拘押营":[["战俘被关在拘押营中。","ئۇرۇش ئەسىرى قاماق لاگېرىدا ساقلىنىۋاتىدۇ.","urush esiri qamaq lagérida saqliniwatidu."]],"拿着鸡毛当令箭":[["他拿着鸡毛当令箭作威作福。","ئۇ توخۇنىڭ پەيىنى پەرمان قىلىپ ئېلىپ ھۆكۈمۈرۈۋاتىدۇ.","u toxuning peyini perman qilip élip hökümürüwatidu."]],"捉迷藏":[["孩子们在花园里玩捉迷藏。","بالىلار باغچىدا يوشۇرۇنچاق ئويناۋاتىدۇ.","balilar baghchida yoshurunchaq oynawatidu."]],"捏估":[["他捏估了一下时间。","ئۇ ۋاقىتنى تەخمىنەن مۆلچەرلىدى.","u waqitni texminen mölcherlidi."]],"扫除机":[["这款扫除机很实用。","بۇ تازىلاش ماشىنىسى ئىنتايىن پايدىلىق.","bu tazilash mashinisi intayin paydiliq."]],"掉泪":[["她听到消息后忍不住掉泪。","ئۇ خەۋەرنى ئاڭلاپ ئۆزىنى تۇتۇپ قالالماي يىغلاپ كەتتى.","u xewerni anglap özini tutup qalalmay yighlap ketti."]],"排水口":[["检查排水口是否通畅。","سۇ چىقىرىش ئېغىزىنىڭ ئوچۇق-تۇتۇق ئەمەسلىكىنى تەكشۈرۈڭ.","su chiqirish éghizining ochuq-tutuq emeslikini tekshürüng."]],"掇刀区":[["掇刀区位于市中心。","دۇئوداۋ رايونى شەھەر مەركىزىدە جايلاشقان.","duodaw rayoni sheher merkizide jaylashqan."]],"授粉":[["蜜蜂帮助花朵授粉。","ھەرە چىۋىنى گۈللەرنىڭ چاڭلاشتۇرۇلۇشىغا ياردەم قىلىدۇ.","here chiwini güllerning changlashturulushigha yardem qilidu."]],"拣饮择食":[["他拣饮择食，挑剔得很。","ئۇ يېمەك-ئىچمەكتە ناھايىتى تاللىغۇچى.","u yémek-ichmekte nahayiti tallighuchi."]],"推助":[["政策推助了当地旅游业的发展。","سىياسەت يەرلىك ساياھەتچىلىك تەرەققىياتىغا ئىتتىرىش كۈچى بەردى.","siyaset yerlik sayahetchilik tereqqiyatigha ittirish küchi berdi."]],"挽辞":[["挽辞中充满了哀悼与祝福。","تەزىيە سۆزىدە ماتەم ۋە ياخشى تىلەكلەر تولۇپ تۇرۇپتۇ.","teziye sözide matem we yaxshi tilekler tolup turuptu."]],"扬鞭":[["他扬鞭催马，加快了行进的速度。","ئۇ قامچىسىنى چېكىپ ئاتنى چاپتۇرۇپ، مېڭىش سۈرئىتىنى تېزلىتىۋەتتى.","u qamchisini chékip atni chapturup, méngish sür'itini tézlitiwetti."]],"换代":[["这款手机完成了技术换代。","بۇ تېلېفون تېخنىكا يېڭىلىنىشىنى تاماملىدى.","bu téléfon téxnika yéngilinishini tamamlidi."]],"挑逗性":[["他的行为很有挑逗性，引人注意。","ئۇنىڭ قىلمىشى بەك مازاقچى، كىشىلەرنىڭ دىققىتىنى تارتىدۇ.","uning qilmishi bek mazaqchi, kishilerning diqqitini tartidu."]],"援兵":[["援兵及时赶到战场。","ياردەمچى قوشۇن ۋاقتىدا جەڭ مەيدانىغا يېتىپ كەلدى.","yardemchi qoshun waqtida jeng meydanigha yétip keldi."]],"抢劫罪":[["他因抢劫罪被法院判处五年有期徒刑。","ئۇ بۇلاڭچىلىق جىنايىتى بىلەن سوت تەرىپىدىن بەش يىللىق قاماق جازاسىغا ھۆكۈم قىلىندى.","u bulangchiliq jinayiti bilen sot teripidin besh yilliq qamaq jazasigha höküm qilindi."]],"搬运工":[["这位搬运工力气很大。","بۇ يۆتكەش ئىشچىسىنىڭ كۈچى بەك چوڭ.","bu yötkesh ishchisining küchi bek chong."]],"摸得着":[["这个按钮摸得着，但按不动。","بۇ كۇنۇپكىنى ئېزىشكە بولىدۇ، ئەمما بېسىشقا بولمايدۇ.","bu kunupkini ézishke bolidu, emma bésishqa bolmaydu."]],"折裙":[["这条折裙设计简洁又时尚。","بۇ قاتلىما يۇپكا ئەتەك لايىھىسى ئاددىي ۋە زامانىۋى.","bu qatlima yupka etek layihisi addiy we zamaniwi."]],"挥杆":[["高尔夫球手挥杆击球。","گولف توپچىسى توپنى ئۇرۇش ئۈچۈن كالتەكنى لىڭشىتتى.","golf topchisi topni urush üchün kaltekni lingshitti."]],"撤营":[["军队在夜间完成撤营。","ئارمىيە كېچىدە لاگېرىنى يىغىشنى تاماملىدى.","armiye kéchide lagérini yighishni tamamlidi."]],"支子":[["他的支子继承家业。","ئۇنىڭ كىچىك ئوغلى ئائىلە ئىشىنى ۋارىسلىق قىلىپ ئالدى.","uning kichik oghli aile ishini warisliq qilip aldi."]],"支恐":[["这种支恐现象令人担忧。","بۇ خىل تېررورلۇقنى قوللاش ھادىسىسى كىشىنى ئەندىشىگە سالىدۇ.","bu xil térrorluqni qollash hadisisi kishini endishige salidu."]],"放射性落下灰":[["放射性落下灰可能污染土壤和水源。","رادىئاتسىيەلىك چۈشكەن كۈل تۇپراق ۋە سۇ مەنبەسىنى بۇلغىشى مۇمكىن.","radiatsiyelik chüshken kül tupraq we su menbesini bulghishi mumkin."]],"教区":[["教区遍布各地。","دىنىي رايون ھەر يەرگە تارقالغان.","diniy rayon her yerge tarqalghan."]],"教科书式":[["这种教科书式的讲解很清晰。","بۇ خىل دەرسلىك كىتابى ئۇسلۇبىدىكى چۈشەندۈرۈش ناھايىتى ئېنىق.","bu xil derslik kitabi uslubidiki chüshendürüsh nahayiti éniq."]],"敬语":[["他在信中使用了恰当的敬语。","ئۇ خەتتە مۇۋاپىق ھۆرمەت سۆزلىرىنى ئىشلەتكەن.","u xette muwapiq hörmet sözlirini ishletken."]],"敢打敢冲":[["这支队伍敢打敢冲，勇猛无畏。","بۇ ئەترەت جۈرئەت بىلەن ئۇرۇشۇپ، قورقماسلىق بىلەن ئالغا ئىلگىرىلەيدۇ.","bu etret jür'et bilen urushup, qorqmasliq bilen algha ilgirileydu."]],"文攻武吓":[["这种文攻武吓的策略很有效。","بۇ خىل ۋېنگۇڭ ۋۇشيا ئىستراتېگىيىسى ئىنتايىن ئۈنۈملۈك.","bu xil wéngung wushya istratégiyisi intayin ünümlük."]],"新台币":[["新台币是台湾地区的官方流通货币。","يېڭى تەيۋەن پۇلى تەيۋەن رايونىنىڭ رەسمىي ئوبوروت پۇلى.","yéngi teywen puli teywen rayonining resmiy oborot puli."]],"新民市":[["新民市交通便利，经济发达。","شىنمىن شەھىرىنىڭ قاتناشى قولايلىق، ئىقتىسادى تەرەققىي قىلغان.","shinmin shehirining qatnashi qolayliq, iqtisadi tereqqiy qilghan."]],"新邱":[["新邱的矿业发达。","شىنچيۇنىڭ كانچىلىقى تەرەققىي قىلغان.","shinchyuning kanchiliqi tereqqiy qilghan."]],"新郑市":[["新郑市是重要的交通枢纽。","شىنجېڭ شەھىرى مۇھىم قاتناش تۈگۈنى.","shinjéng shehiri muhim qatnash tügüni."]],"新新人类":[["新新人类追求创新生活。","يېڭى ئەۋلاد ئىنسانلار يېڭىلىق يارىتىش تۇرمۇشىنى ئىزدەيدۇ.","yéngi ewlad insanlar yéngiliq yaritish turmushini izdeydu."]],"新山":[["新山是马来西亚的重要城市。","شىنشەن مالايسىيانىڭ مۇھىم شەھىرى.","shinshen malaysiyaning muhim shehiri."]],"断乎":[["他断乎不会接受这个提议。","ئۇ بۇ تەكلىپنى ھەرگىز قوبۇل قىلمايدۇ.","u bu teklipni hergiz qobul qilmaydu."]],"断线钳":[["用断线钳剪断电线。","تور ئۈزۈش ئەسۋابى بىلەن توك سىمىنى كېسىپ ئۈزدى.","tor üzüsh eswabi bilen tok simini késip üzdi."]],"断线风筝":[["断线风筝越飞越高。","ئۈزۈلگەن سىملىق پەلەمپەي بارغانسېرى ئېگىز ئۇچتى.","üzülgen simliq pelempey barghanséri égiz uchti."]],"旁观者清":[["旁观者清，当局者迷。","كۆزەتكۈچى ئېنىق، ئىش ئىگىسى گاڭگىراپ قالىدۇ.","közetküchi éniq, ish igisi ganggirap qalidu."]],"旁遮普":[["旁遮普地区盛产小麦。","پەنجاب رايونى بۇغدايغا باي.","penjab rayoni bughdaygha bay."]],"早老性痴呆":[["这是一种早老性痴呆。","بۇ بىر خىل بالدۇر قېرىش خاراكتېرلىك ئەخمىقىيەت.","bu bir xil baldur qérish xaraktérlik exmiqiyet."]],"旮旯":[["街角的小旮旯藏着家好店。","كوچا بۇلۇڭىدىكى كىچىك بۇرجەكتە ياخشى دۇكان بار.","kocha bulungidiki kichik burjekte yaxshi dukan bar."]],"明尼苏达州":[["明尼苏达州以湖泊和森林闻名。","مىننېسوتا شتاتى كۆللەر ۋە ئورمانلار بىلەن داڭلىق.","minnésota shtati köller we ormanlar bilen dangliq."]],"春日乡":[["春日乡风景如画，令人向往。","چۇنرى يېزىسىنىڭ مەنزىرىسى رەسىمدەك گۈزەل، كىشىنى ئىنتىلدۈرىدۇ.","chunri yézisining menzirisi resimdek güzel, kishini intildüridu."]],"春分":[["春分时节，昼夜时长相等。","باھار تەڭلىك مەزگىلىدە كۈندۈز بىلەن كېچىنىڭ ئۇزۇنلۇقى تەڭ بولىدۇ.","bahar tenglik mezgilide kündüz bilen kéchining uzunluqi teng bolidu."]],"昌吉州":[["昌吉州以畜牧业闻名。","چاڭجى ئوبلاستى چارۋىچىلىق بىلەن داڭلىق.","changji oblasti charwichiliq bilen dangliq."]],"普什图语":[["普什图语是阿富汗的主要语言之一。","پۇشتۇ تىلى ئافغانىستاننىڭ ئاساسلىق تىللىرىنىڭ بىرى.","pushtu tili afghanistanning asasliq tillirining biri."]],"时间线":[["这部电影的时间线非常清晰。","بۇ كىنونىڭ ۋاقىت لىنىيىسى ناھايىتى ئېنىق.","bu kinoning waqit liniyisi nahayiti éniq."]],"普通𫛭":[["普通𫛭的叫声非常清脆。","ئادەتتىكى قىيا چىمچىقىنىڭ ئاۋازى ئىنتايىن سۈزۈك.","adettiki qiya chimchiqining awazi intayin süzük."]],"暗送秋波":[["他偷偷地暗送秋波。","ئۇ ئوغرىلىقچە يوشۇرۇن كۆز قىسىپ قويدى.","u oghriliqche yoshurun köz qisip qoydi."]],"书画家":[["他是远近闻名的书画家。","ئۇ يىراق-يېقىنغا مەشھۇر رەسسام ۋە خەتتاتتۇر.","u yiraq-yéqingha meshhur ressam we xettattur."]],"书箧":[["书箧是古代用来携带书籍的容器。","كىتاب ساندۇقى قەدىمدە كىتابلارنى ئېلىپ يۈرۈشكە ئىشلىتىلگەن ساۋۇتتۇر.","kitab sanduqi qedimde kitablarni élip yürüshke ishlitilgen sawuttur."]],"有枝有叶":[["这棵树有枝有叶，很茂盛。","بۇ دەرەخ شاخ-شۇمبىلىق ۋە كۆپىنچە يوپۇرماقلىق، بەك كۆكلىگەن.","bu derex shax-shumbiliq we köpinche yopurmaqliq, bek kökligen."]],"有条纹":[["这件衣服有条纹图案。","بۇ كىيىمنىڭ يول-يول نەقىشلىرى بار.","bu kiyimning yol-yol neqishliri bar."]],"木偶戏":[["木偶戏是一种传统的表演艺术。","قورچاق ئويۇنى ئەنئەنىۋى ئىپادىلەش سەنئىتى.","qorchaq oyuni en'eniwi ipadilesh sen'iti."]],"期冀":[["我们对未来充满期冀与希望。","بىز كەلگۈسىگە ئۈمىد ۋە ئارزۇ بىلەن تولدۇق.","biz kelgüsige ümid we arzu bilen tolduq."]],"有罪":[["他确实有罪，必须受到惩罚。","ئۇ ھەقىقەتەن گۇناھكار، چوقۇم جازالىنىشى كېرەك.","u heqiqeten gunahkar, choqum jazalinishi kérek."]],"望楼":[["古时有专门的望楼。","قەدىمكى زاماندا مەخسۇس كۆزىتىش مۇنارى بار ئىدى.","qedimki zamanda mexsus közitish munari bar idi."]],"李鹏":[["李鹏曾担任过国家领导人。","لى پېڭ ئىلگىرى دۆلەت رەھبىرى بولغان.","li péng ilgiri dölet rehbiri bolghan."]],"杏仁体":[["杏仁体参与情绪调节功能。","بادام تەنچىسى ھېسسىياتنى تەڭشەش ئىقتىدارىغا قاتنىشىدۇ.","badam tenchisi héssiyatni tengshesh iqtidarigha qatnishidu."]],"东宝":[["东宝公司推出了新产品。","دۇڭباۋ شىركىتى يېڭى مەھسۇلاتلارنى تونۇشتۇردى.","dungbaw shirkiti yéngi mehsulatlarni tonushturdi."]],"东川":[["东川的矿产资源丰富。","دۇڭچۈەننىڭ مىنېرال بايلىقلىرى مول.","dungchüenning minéral bayliqliri mol."]],"杞国忧天":[["杞国忧天是经典的寓言故事。","قىي دۆلىتىنىڭ ئاسماندىن قورقۇشى كلاسسىك تەمسىل ھېكايىسىدۇر.","qiy dölitining asmandin qorqushi klassik temsil hékayisidur."]],"松北区":[["松北区位于城市北部。","سۇڭبېي رايونى شەھەرنىڭ شىمالىي قىسمىدا جايلاشقان.","sungbéy rayoni sheherning shimaliy qismida jaylashqan."]],"松原市":[["松原市以湿地闻名。","سۇڭيۈەن شەھىرى سۇلۇق يەرلەر بىلەن داڭلىق.","sungyüen shehiri suluq yerler bilen dangliq."]],"东芝":[["东芝是知名电器品牌。","توشىبا تونۇلغان ئېلېكتر سايمانلىرى ماركىسى.","toshiba tonulghan éléktr saymanliri markisi."]],"林来疯":[["林来疯是一个音乐节的名称。","ئورمان مەجنۇنىتى بىر مۇزىكا بايرىمىنىڭ نامى.","orman mejnuniti bir muzika bayrimining nami."]],"林甸":[["林甸的草原风景十分壮丽。","لىندىيەنىڭ يايلاق مەنزىرىسى ناھايىتى ھەيۋەتلىك.","lindiyening yaylaq menzirisi nahayiti heywetlik."]],"东陵区":[["东陵区是沈阳市的一个行政区。","دۇڭلىڭ رايونى شېنياڭ شەھىرىدىكى بىر مەمۇرىي رايون.","dungling rayoni shényang shehiridiki bir memuriy rayon."]],"柔肠寸断":[["听到消息后，他柔肠寸断，悲痛欲绝。","خەۋەرنى ئاڭلىغاندىن كېيىن، ئۇنىڭ يۈرىكى پارە-پارە بولۇپ، قاتتىق قايغۇردى.","xewerni anglighandin kéyin, uning yüriki pare-pare bolup, qattiq qayghurdi."]],"枷带锁抓":[["古代刑罚包括枷带锁抓。","قەدىمكى جازالار كىشەن ۋە قۇلۇپ سېلىشنى ئۆز ئىچىگە ئالىدۇ.","qedimki jazalar kishen we qulup sélishni öz ichige alidu."]],"柿子椒":[["柿子椒是烹饪常用食材。","خۇرما بۇرچى ئاشخانا تەييارلىقىدا كۆپ ئىشلىتىلىدىغان يېمەكلىك ماتېرىيالىدۇر.","xurma burchi ashxana teyyarliqida köp ishlitilidighan yémeklik matériyalidur."]],"核对":[["请仔细核对账目中的数字。","ھېسابات دەپتەرىدىكى سانلارنى ئەستايىدىل سېلىشتۇرۇپ تەكشۈرۈڭ.","hésabat depteridiki sanlarni estayidil sélishturup tekshürüng."]],"核弹":[["核弹是一种威力巨大的武器。","يادرو بومبا كۈچى زور قورالدۇر.","yadro bomba küchi zor qoraldur."]],"格斯塔":[["格斯塔是当地著名的旅游景点。","گېستا يەرلىك ئاتاقلىق ساياھەت نۇقتىسى.","gésta yerlik ataqliq sayahet nuqtisi."]],"柳暗花明":[["柳暗花明比喻在困境中看到希望，事情出现转机。","ليۇئەنخۇامىڭ قىيىنچىلىق ئىچىدە ئۈمىد كۆرۈشنى، ئىشنىڭ ئەھۋالى ئۆزگىرىپ ياخشىلانغانلىقىنى تەمسىل قىلىدۇ.","lyuenxuaming qiyinchiliq ichide ümid körüshni, ishning ehwali özgirip yaxshilanghanliqini temsil qilidu."]],"桌面儿上":[["桌面儿上放着一杯热茶。","ئۈستەل يۈزىدە بىر ئىستاكان ئىسسىق چاي تۇرۇپتۇ.","üstel yüzide bir istakan issiq chay turuptu."]],"桎梏":[["传统观念有时会成为创新的桎梏。","ئەنئەنىۋى چۈشەنچە بەزىدە يېڭىلىق يارىتىشنىڭ كىشەنلىرىگە ئايلىنىپ قالىدۇ.","en'eniwi chüshenche bezide yéngiliq yaritishning kishenlirige aylinip qalidu."]],"梁静茹":[["梁静茹是一位知名的流行歌手。","Liang Jingru bolsa تونۇلغان ئاممىباپ ناخشىچى.","Liang Jingru bolsa tonulghan ammibap naxshichi."]],"棉兰老岛":[["棉兰老岛是菲律宾最大的岛屿。","مېداناۋ ئارىلى فىلىپپىننىڭ ئەڭ چوڭ ئارىلى.","médanaw arili filippinning eng chong arili."]],"梯子":[["梯子靠在墙上，方便上下攀爬。","شوتا تامغا يۆلەنگەن بولۇپ، چىقىش-چۈشۈشكە قولايلىق.","shota tamgha yölengen bolup, chiqish-chüshüshke qolayliq."]],"棕叶":[["这片棕叶已经快要枯萎了。","بۇ قوڭۇر يوپۇرماق ئاللىبۇرۇن سولىشىپ قالغىلى تاس قالدى.","bu qongur yopurmaq alliburun soliship qalghili tas qaldi."]],"枣庄":[["枣庄是山东省的一座城市。","زاۋجۇاڭ شەندۇڭ ئۆلكىسىدىكى بىر شەھەر.","zawjuang shendung ölkisidiki bir sheher."]],"极客":[["这位极客对编程充满热情。","بۇ گېك پروگراممىلاشقا ئىنتايىن قىزىقىدۇ.","bu gék programmilashqa intayin qiziqidu."]],"乐山市":[["乐山市是四川省的一座重要城市。","لېشەن شەھىرى سىچۇەن ئۆلكىسىدىكى مۇھىم بىر شەھەر.","léshen shehiri sichuen ölkisidiki muhim bir sheher."]],"标注":[["请对图表中的关键部分进行标注。","جەدۋەلدىكى مۇھىم قىسىملارغا ئۆلچەم بەلگىسى قويۇڭ.","jedweldiki muhim qisimlargha ölchem belgisi qoyung."]],"概念地图":[["这张概念地图清晰展示了关联。","بۇ ئۇقۇم خەرىتىسى باغلىنىشلارنى ئېنىق نامايان قىلىدۇ.","bu uqum xeritisi baghlinishlarni éniq namayan qilidu."]],"榕城区":[["榕城区是揭阳市的主要城区。","رۇڭچېڭ رايونى جيېياڭ شەھىرىنىڭ ئاساسلىق شەھەر رايونىدۇر.","rungchéng rayoni jyéyang shehirining asasliq sheher rayonidur."]],"机翻":[["机翻软件偶尔会出现错误。","ماشىنا تەرجىمە يۇمشاق دېتالى بەزىدە خاتالىق كۆرسىتىدۇ.","mashina terjime yumshaq détali bezide xataliq körsitidu."]],"槐树":[["庭院里种着一棵古老的槐树。","ھويلىدا بىر دانە قەدىمىي سۆگەت دەرىخى تىكىلگەن.","hoylida bir dane qedimiy söget derixi tikilgen."]],"杠荡":[["杠荡是一种传统的民间舞蹈。","گاڭداڭ ئەنئەنىۋى بىر خىل خەلق ئۇسسۇلىدۇر.","gangdang en'eniwi bir xil xelq ussulidur."]],"检证":[["检证过程需要严格的身份验证。","تەكشۈرۈش جەريانى قاتتىق شەخسىيەتنى دەلىللەشنى تەلەپ قىلىدۇ.","tekshürüsh jeryani qattiq shexsiyetni delilleshni telep qilidu."]],"树液":[["树液对植物生长至关重要。","دەرەخ شىرنىسى ئۆسۈملۈكلەرنىڭ ئۆسۈشى ئۈچۈن ئىنتايىن مۇھىم.","derex shirnisi ösümlüklerning ösüshi üchün intayin muhim."]],"榨汁机":[["榨汁机可以制作新鲜果汁。","شىرنە سىققۇچ يېڭى مېۋە شىرنىسى ياسىيالايدۇ.","shirne siqquch yéngi méwe shirnisi yasiyalaydu."]],"欲取姑与":[["欲取姑与体现了智慧。","ئېلىشنى خالىساڭ ئاۋۋال بەرگىن دېگەن ئەقىل-پاراسەتنى ئىپادىلەيدۇ.","élishni xalisang awwal bergin dégen eqil-parasetni ipadileydu."]],"欠条":[["欠条是借款时的重要凭证。","قەرز خېتى پۇل ئارىيەت ئالغاندا مۇھىم ئىسپاتتۇر.","qerz xéti pul ariyet alghanda muhim ispattur."]],"正字法":[["正字法用于规范汉字的书写。","ئىملائى قائىدە خەنزۇ يېزىقىنىڭ يېزىلىشىنى قېلىپلاشتۇرۇشقا ئىشلىتىلىدۇ.","imlai qaide xenzu yéziqining yézilishini qéliplashturushqa ishlitilidu."]],"正宁县":[["正宁县以苹果种植业著称。","جېڭنىڭ ناھىيىسى ئالما ئۆستۈرۈش كەسپى بىلەن داڭلىق.","jéngning nahiyisi alma östürüsh kespi bilen dangliq."]],"正常化":[["数据需要经过正常化处理。","سانلىق مەلۇماتلارنى نورماللاشتۇرۇش بىر تەرەپ قىلىشتىن ئۆتكۈزۈشكە توغرا كېلىدۇ.","sanliq melumatlarni normallashturush bir terep qilishtin ötküzüshke toghra kélidu."]],"壳幔":[["地壳幔层是地球的重要结构。","يەر قاتقى مانتىيە قەۋىتى يەر شارىنىڭ مۇھىم قۇرۇلمىسىدۇر.","yer qatqi mantiye qewiti yer sharining muhim qurulmisidur."]],"杀出重围":[["军队成功杀出重围，取得胜利。","ئارمىيە مۇۋەپپەقىيەتلىك ھالدا قورشاۋدىن بۆسۈپ چىقىپ، غەلىبە قازاندى.","armiye muweppeqiyetlik halda qorshawdin bösüp chiqip, ghelibe qazandi."]],"每日新闻":[["每日新闻涵盖全球热点事件。","كۈندىلىك خەۋەرلەر دۇنيا مىقياسىدىكى قىزىق نۇقتىلىق ۋەقەلەرنى ئۆز ئىچىگە ئالىدۇ.","kündilik xewerler dunya miqyasidiki qiziq nuqtiliq weqelerni öz ichige alidu."]],"比捕":[["他们比捕鱼的技巧。","ئۇلار بېلىق تۇتۇش ماھارىتىنى سېلىشتۇرىدۇ.","ular béliq tutush maharitini sélishturidu."]],"毛里塔尼亚":[["毛里塔尼亚位于非洲西部。","ماۋرىتانىيە ئافرىقىنىڭ غەربىدە جايلاشقان.","mawritaniye afriqining gherbide jaylashqan."]],"民族大迁徙":[["民族大迁徙改变了历史进程。","مىللەتلەرنىڭ چوڭ كۆچىشى تارىخ جەريانىنى ئۆزگەرتكەن.","milletlerning chong köchishi tarix jeryanini özgertken."]],"殚力":[["他殚力完成这项任务。","ئۇ بۇ ۋەزىپىنى ئادا قىلىش ئۈچۈن بار كۈچىنى سەرپ قىلدى.","u bu wezipini ada qilish üchün bar küchini serp qildi."]],"氰溴甲苯":[["氰溴甲苯是一种有机合成原料。","سىيانبرومتولۇئول ئورگانىك سىنتېزلىشىدىغان خام ماتېرىيال.","siyanbromtoluol organik sintézlishidighan xam matériyal."]],"水晶球":[["他用水晶球占卜未来的运势。","ئۇ كرىستال شار ئارقىلىق كەلگۈسى تەلەيىنى پاللىدى.","u kristal shar arqiliq kelgüsi teleyini pallidi."]],"水兵":[["水兵是海军中负责操作舰船的人员。","دېڭىز ئەسكەرى دېڭىز ئارمىيەسىدە كېمە پىلاستىرىشنى باشقۇرىدىغان خادىم.","déngiz eskeri déngiz armiyeside kéme pilastirishni bashquridighan xadim."]],"江西省":[["江西省位于中国东南部地区。","جياڭشى ئۆلكىسى جۇڭگونىڭ جەنۇبىي شەرقىي رايونىدا جايلاشقان.","jyangshi ölkisi junggoning jenubiy sherqiy rayonida jaylashqan."]],"沃壤":[["沃壤适合种植各种农作物。","مۇنبەت تۇپراق ھەر خىل يېزا ئىگىلىك زىرائەتلىرىنى تىكىشكە ماس كېلىدۇ.","munbet tupraq her xil yéza igilik ziraetlirini tikishke mas kélidu."]],"汾西":[["汾西地区以煤炭资源丰富而闻名。","فېنشى رايونى كۆمۈر بايلىقىنىڭ موللۇقى بىلەن تونۇلغان.","fénshi rayoni kömür bayliqining molluqi bilen tonulghan."]],"汝州市":[["汝州市是河南省的地级市。","رۇجۇ شەھىرى خېنەن ئۆلكىسىنىڭ ۋىلايەت دەرىجىلىك شەھىرى.","ruju shehiri xénen ölkisining wilayet derijilik shehiri."]],"沾湿":[["雨水沾湿了她的头发。","يېغىن سۇ ئۇنىڭ چېچىنى ھۆل قىلدى.","yéghin su uning chéchini höl qildi."]],"河畔":[["河畔的柳树在微风中轻轻摇曳。","دەريا بويىدىكى سۆگەتلەر شامالدا ئاستا تەۋرىنىدۇ.","derya boyidiki sögetler shamalda asta tewrinidu."]],"河间市":[["河间市位于河北省中部。","خېجياڭ شەھىرى خېبېي ئۆلكىسىنىڭ ئوتتۇرىسىدا جايلاشقان.","xéjyang shehiri xébéy ölkisining otturisida jaylashqan."]],"波普艺术":[["波普艺术是20世纪的重要艺术流派。","پوپ ئارتىسلىقى 20-ئەسىرنىڭ مۇھىم سەنئەت ئېقىمى.","pop artisliqi 20-esirning muhim sen'et éqimi."]],"波季":[["波季是乌克兰的一个城市。","پوتى ئۇكرائىنادىكى بىر شەھەردۇر.","poti ukrainadiki bir sheherdur."]],"沙特鲁":[["沙特鲁是当地的一种传统舞蹈。","سەئۇدى رەقسى يەرلىك ئەنئەنىۋى ئۇسسۇلنىڭ بىر تۈرىدۇر.","seudi reqsi yerlik en'eniwi ussulning bir türidur."]],"沙鹿镇":[["沙鹿镇以出产优质茶叶而闻名。","شالۇ بازىرى سۈپەتلىك چاي ئىشلەپچىقىرىشى بىلەن داڭلىقتۇر.","shalu baziri süpetlik chay ishlepchiqirishi bilen dangliqtur."]],"法家":[["法家是中国古代的重要学派。","قانۇنپەرەسلىك جۇڭگونىڭ قەدىمكى زاماندىكى مۇھىم مەكتىپىدۇر.","qanunpereslik junggoning qedimki zamandiki muhim mektipidur."]],"泰然自若":[["面对困难，他泰然自若。","قىيىنچىلىققا دۇچ كەلگەندە، ئۇ تىنچلىق بىلەن مۇئامىلە قىلىدۇ.","qiyinchiliqqa duch kelgende, u tinchliq bilen muamile qilidu."]],"洞察":[["他总能洞察别人内心的想法。","ئۇ ھەمىشە باشقىلارنىڭ كۆڭلىدىكى ئويلىرىنى چۈشىنىپ يېتەلەيدۇ.","u hemishe bashqilarning könglidiki oylirini chüshinip yételeydu."]],"洛佩斯":[["洛佩斯是著名的足球运动员。","لوپېس داڭلىق پۇتبولچى.","lopés dangliq putbolchi."]],"流形":[["流形是数学中的一个复杂概念。","مانىفولد ماتېماتىكىدىكى مۇرەككەپ چۈشەنچە.","manifold matématikidiki murekkep chüshenche."]],"海员":[["海员在海上工作多年。","دېڭىزچىلار دېڭىزدا كۆپ يىللاردىن بۇيان خىزمەت قىلىدۇ.","déngizchilar déngizda köp yillardin buyan xizmet qilidu."]],"海德堡":[["海德堡是一座历史悠久的古城。","خەيدېلبېرگ ئۇزۇن تارىخقا ئىگە قەدىمىي شەھەر.","xeydélbérg uzun tarixqa ige qedimiy sheher."]],"海战":[["这场海战改变了历史的走向。","بۇ دېڭىز جېڭى تارىخنىڭ يۆنىلىشىنى ئۆزگەرتتى.","bu déngiz jéngi tarixning yönilishini özgertti."]],"海淘":[["通过海淘，我可以买到国外的商品。","دېڭىز ئارقىلىق سېتىۋېلىش ئارقىلىق، مەن چەت ئەل مەھسۇلاتلىرىنى سېتىۋالالايمەن.","déngiz arqiliq sétiwélish arqiliq, men chet el mehsulatlirini sétiwalalaymen."]],"海百合":[["海百合是海洋生物。","دېڭىز نىلۇپىرى دېڭىز جانلىقىدۇر.","déngiz nilupiri déngiz janliqidur."]],"涅瓦":[["涅瓦河是俄罗斯的重要河流。","نېۋا دەرياسى رۇسىيەنىڭ مۇھىم دەرياسىدۇر.","néwa deryasi rusiyening muhim deryasidur."]],"泾县":[["泾县位于安徽省东南部。","جىڭشەن ناھىيىسى ئەنخۇي ئۆلكىسىنىڭ جەنۇبىي شەرقىدە جايلاشقان.","jingshen nahiyisi enxuy ölkisining jenubiy sherqide jaylashqan."]],"涓滴":[["每一涓滴都很珍贵。","ھەر بىر تامچە سۇ ئىنتايىن قىممەتلىك.","her bir tamche su intayin qimmetlik."]],"涵盖":[["这项政策涵盖了多个方面。","بۇ سىياسەت كۆپلىگەن تەرەپلەرنى ئۆز ئىچىگە ئالىدۇ.","bu siyaset köpligen tereplerni öz ichige alidu."]],"涸辙之鲋":[["他处境如同涸辙之鲋，急需帮助。","ئۇنىڭ ئەھۋالى قۇرۇق ئېرىقتىكى بېلىققا ئوخشاش، ئۇنىڭغا جىددىي ياردەم كېرەك.","uning ehwali quruq ériqtiki béliqqa oxshash, uninggha jiddiy yardem kérek."]],"淄川区":[["淄川区以优质的陶瓷产品著称。","زىچۇەن رايونى سۈپەتلىك فارفور مەھسۇلاتلىرى بىلەن تونۇلغان.","zichuen rayoni süpetlik farfor mehsulatliri bilen tonulghan."]],"淇滨":[["淇滨是鹤壁市的一个区。","چىبىن خېبى شەھىرىنىڭ بىر رايونى.","chibin xébi shehirining bir rayoni."]],"淤泥":[["湖底的淤泥需要定期清理。","كۆل ئاستىدىكى لازىنى مۇنتىزىم تازىلاش كېرەك.","köl astidiki lazini muntizim tazilash kérek."]],"清浦":[["清浦是一个历史名城。","چىڭپۇ تارىخىي داڭلىق شەھەر.","chingpu tarixiy dangliq sheher."]],"渭城":[["渭城是古代著名的诗歌题材。","ۋېيچېڭ قەدىمكى دەۋردىكى مەشھۇر شېئىرىيەت تېمىسى.","wéychéng qedimki dewrdiki meshhur shéiriyet témisi."]],"海鞘":[["海鞘是一种海洋生物。","دېڭىز قاپقىقى بىر خىل دېڭىز جانلىقىدۇر.","déngiz qapqiqi bir xil déngiz janliqidur."]],"减数":[["这次考试人数有所减数。","بۇ قېتىمقى ئىمتىھانغا قاتناشقۇچىلار سانى بىر ئاز ئازايدى.","bu qétimqi imtihangha qatnashquchilar sani bir az azaydi."]],"准噶尔翼龙":[["准噶尔翼龙是一种古老的飞行爬行动物。","جۇڭغار پتېروداكتىلى قەدىمكى ئۇچقۇچى ئەجدىھادۇر.","jungghar ptérodaktili qedimki uchquchi ejdihadur."]],"溯源":[["科学家们正在溯源污染物的来源。","ئالىملار بۇلغىغۇچى ماددىلارنىڭ مەنبەسىنى ئىزدەۋاتىدۇ.","alimlar bulghighuchi maddilarning menbesini izdewatidu."]],"溺死":[["他因溺水而溺死。","ئۇ سۇغا چۆكۈپ غەرق بولۇپ ئۆلدى.","u sugha chöküp gherq bolup öldi."]],"滕家":[["滕家世代以酿酒闻名。","تېڭ ئائىلىسى ئەۋلادتىن ئەۋلادقا ھاراق ئېچىش بىلەن تونۇلغان.","téng ailisi ewladtin ewladqa haraq échish bilen tonulghan."]],"温床":[["潮湿的环境成了病菌的温床。","نەم مۇھىت باكتېرىيەلەرنىڭ ئىسسىق كارىۋىتىغا ئايلاندى.","nem muhit baktériyelerning issiq kariwitigha aylandi."]],"沤肥":[["沤肥可以改善土壤。","چىرىتىلغان ئوغۇت تۇپراقنى ياخشىلايدۇ.","chiritilghan oghut tupraqni yaxshilaydu."]],"渔雕":[["渔雕是一种以鱼为食的雕。","بېلىق بۈركۈتى بېلىق بىلەن ئوزۇقلىنىدىغان بىر خىل بۈركۈتتۇر.","béliq bürküti béliq bilen ozuqlinidighan bir xil bürküttur."]],"满脸风尘":[["他满脸风尘，显然经历了长途跋涉的艰辛。","ئۇنىڭ چىرايى توپا-چاڭغا تولغان بولۇپ، ئۇزۇن سەپەرنىڭ جاپاسىنى تارتقانلىقى ئېنىق.","uning chirayi topa-changgha tolghan bolup, uzun seperning japasini tartqanliqi éniq."]],"渐近":[["曲线逐渐渐近于直线。","ئەگرى سىزىق تەدرىجىي تۈز سىزىققا يېقىنلىشىۋاتىدۇ.","egri siziq tedrijiy tüz siziqqa yéqinlishiwatidu."]],"潞西市":[["潞西市曾是重要的交通枢纽。","لۇشى شەھىرى ئىلگىرى مۇھىم قاتناش تۈگۈنى ئىدى.","lushi shehiri ilgiri muhim qatnash tügüni idi."]],"澡堂":[["澡堂是公共沐浴的场所。","مۇنچىخانا ئاممىۋى يۇيۇنۇش ئورنى.","munchixana ammiwi yuyunush orni."]],"泽州":[["泽州是古代的重要州府。","زېجو قەدىمدىكى مۇھىم ئۆلكە مەركىزى.","zéjo qedimdiki muhim ölke merkizi."]],"火舌":[["火焰像火舌般舔着锅底。","ئوت يالقۇنى ئوت تىلىدەك قازان ئاستىنى يالايدۇ.","ot yalquni ot tilidek qazan astini yalaydu."]],"灰鹱":[["灰鹱常在海面上飞行。","كۈلرەڭ چاچقۇچى قۇش دائىم دېڭىز يۈزىدە ئۇچىدۇ.","külreng chachquchi qush daim déngiz yüzide uchidu."]],"灶具":[["现代厨房配备了多种灶具。","زامانىۋى ئاشخانا كۆپ خىل ئوچاق ئۈسكۈنىلىرى بىلەن جابدۇلغان.","zamaniwi ashxana köp xil ochaq üsküniliri bilen jabdulghan."]],"浇注":[["浇注过程中需要保持温度稳定。","قۇيۇش جەريانىدا تېمپېراتۇرىنى مۇقىم ساقلىشى كېرەك.","quyush jeryanida témpératurini muqim saqlishi kérek."]],"炮艇机":[["炮艇机是一种支援舰艇的飞机。","توپ قېيىق ئايروپىلانى قوللايدىغان كېمە ئايروپىلانىدۇر.","top qéyiq ayropilani qollaydighan kéme ayropilanidur."]],"为非作歹":[["他们为非作歹，扰乱社会秩序。","ئۇلار يامانلىق قىلىپ، جەمئىيەت تەرتىپىنى بۇزىدۇ.","ular yamanliq qilip, jem'iyet tertipini buzidu."]],"烘焙":[["她喜欢在家尝试烘焙。","ئۇ ئۆيدە پىشۇرۇش سىناپ كۆرۈشنى ياخشى كۆرىدۇ.","u öyde pishurush sinap körüshni yaxshi köridu."]],"烦忧":[["他的烦忧始终挥之不去。","ئۇنىڭ غەم-قايغۇسى داۋاملىق يوقالمىدى.","uning ghem-qayghusi dawamliq yoqalmidi."]],"烟花女":[["烟花女曾是舞台上耀眼的明星。","ئاتەش ئويۇنى قىزى سەھنىدىكى پارلاق يۇلتۇز ئىدى.","atesh oyuni qizi sehnidiki parlaq yultuz idi."]],"牙克石市":[["牙克石市以草原风光闻名。","ياقشى شەھىرى يايلاق مەنزىرىسى بىلەن تونۇلغان.","yaqshi shehiri yaylaq menzirisi bilen tonulghan."]],"牌位":[["牌位上刻着祖先的名字。","يادنامە تاختىسىغا ئەجدادلارنىڭ ئىسىملىرى ئويۇلغان.","yadname taxtisigha ejdadlarning isimliri oyulghan."]],"牙人":[["牙人负责替买卖双方牵线搭桥。","دەللالمچى سېتىۋالغۇچى بىلەن ساتقۇچى ئارىسىدا ئالاقە باغلاشقا مەسئۇل.","dellalmchi sétiwalghuchi bilen satquchi arisida alaqe baghlashqa mes'ul."]],"燃料电池":[["燃料电池为航天器提供了稳定的能源。","يېقىلغۇ باتارېيىسى ئالەم كېمىسىگە مۇقىم ئېنېرگىيە تەمىنلىدى.","yéqilghu bataréyisi alem kémisige muqim énérgiye teminlidi."]],"燃煤":[["燃煤是传统发电的主要能源之一。","كۆمۈر يېقىش ئەنئەنىۋى توك چىقىرىشنىڭ مۇھىم ئېنېرگىيە مەنبەلىرىنىڭ بىرى.","kömür yéqish en'eniwi tok chiqirishning muhim énérgiye menbelirining biri."]],"狼崽":[["狼崽刚出生时眼睛是闭着的。","بۆرە كۈچۈكى تۇغۇلغاندا كۆزلىرى يۇمۇق بولىدۇ.","böre küchüki tughulghanda közliri yumuq bolidu."]],"特种兵":[["特种兵训练非常严格。","ئالاھىدە ئەسكەرلەرنىڭ مەشىقى ئىنتايىن قاتتىق.","alahide eskerlerning meshiqi intayin qattiq."]],"玉溪":[["玉溪是云南省的一座美丽城市。","يۈشى يۈننەن ئۆلكىسىدىكى بىر گۈزەل شەھەر.","yüshi yünnen ölkisidiki bir güzel sheher."]],"玻璃罩":[["玻璃罩保护着里面的展品。","ئەينەك قاپقاق ئىچىدىكى كۆرگەزمە بۇيۇملىرىنى قوغدايدۇ.","eynek qapqaq ichidiki körgezme buyumlirini qoghdaydu."]],"琐屑":[["这些琐屑之事实在令人头疼。","بۇ ئۇششاق ئىشلار ھەقىقەتەن باش ئاغرىتىدۇ.","bu ushshaq ishlar heqiqeten bash aghritidu."]],"瑶海":[["瑶海是一片美丽的湖泊。","ياۋخەي چىرايلىق بىر كۆل.","yawxey chirayliq bir köl."]],"生卒年":[["请写下生卒年。","تۇغۇلغان ۋە ئۆلگەن يىلىنى يېزىڭ.","tughulghan we ölgen yilini yézing."]],"留空":[["表格中留空部分需自行填写。","جەدۋەلدىكى بوش قالدۇرۇلغان قىسىمنى ئۆزىڭىز تولدۇرۇشىڭىز كېرەك.","jedweldiki bosh qaldurulghan qisimni özingiz toldurushingiz kérek."]],"甩上":[["他把外套甩上肩膀。","ئۇ چاپىنىنى يېلىپ مۈرىسىگە ئاتتى.","u chapinini yélip mürisige atti."]],"病苦":[["战争给人民带来了无尽的病苦。","ئۇرۇش خەلققە تۈگىمەس كېسەل ئازابى ئېلىپ كەلدى.","urush xelqqe tügimes késel azabi élip keldi."]],"发射机应答器":[["发射机应答器确保通信稳定。","ئاتقۇچ ئاپپارات جاۋاب بەرگۈچىسى ئالاقىنىڭ مۇقىم بولۇشىنى كاپالەتكە ئىگە قىلىدۇ.","atquch apparat jawab bergüchisi alaqining muqim bolushini kapaletke ige qilidu."]],"白颊鹎":[["白颊鹎的羽毛色彩鲜艳。","ئاق ياقىلىق زاغچىنىڭ پەيلىرى رەڭگارەڭ ۋە چىرايلىق.","aq yaqiliq zaghchining peyliri renggareng we chirayliq."]],"登台表演":[["她今晚将登台表演小提琴独奏。","ئۇ بۈگۈن كەچتە سەھنىگە چىقىپ سكرىپكا يالغۇز چالىدۇ.","u bügün kechte sehnige chiqip skripka yalghuz chalidu."]],"白额雁":[["白额雁是迁徙的候鸟。","ئاق پېشانىلىك غاز كۆچمەن قۇش.","aq péshanilik ghaz köchmen qush."]],"白纸黑字":[["合同上白纸黑字写得清清楚楚。","توختامدا ئاق قەغەزگە قارا خەت بىلەن ئېنىق يېزىلغان.","toxtamda aq qeghezge qara xet bilen éniq yézilghan."]],"硒鼓":[["硒鼓是打印机的关键部件。","سېلېن گېلىستىرىگىسى پرىنتېرنىڭ مۇھىم زاپچاسىدۇر.","sélén gélistirigisi printérning muhim zapchasidur."]],"磨脚石":[["磨脚石可以缓解足部疲劳。","پۇت تېشىنى ئۇيۇش تېشى پۇتنىڭ چارچىشىنى يېنىكلىتەلەيدۇ.","put téshini uyush téshi putning charchishini yénikliteleydu."]],"石鲮鱼":[["石鲮鱼是广东地区常见的鱼类。","شىلىڭ بېلىقى گۇاڭدۇڭ رايونىدا كۆپ ئۇچرايدىغان بېلىق تۈرى.","shiling béliqi guangdung rayonida köp uchraydighan béliq türi."]],"社长":[["社长主持会议。","جەمئىيەت باشلىقى يىغىنغا رىياسەتچىلىك قىلدى.","jem'iyet bashliqi yighingha riyasetchilik qildi."]],"符合标准":[["这个方案完全符合标准。","بۇ پىلان ئۆلچەمگە پۈتۈنلەي ئۇيغۇن.","bu pilan ölchemge pütünley uyghun."]],"结肠炎":[["结肠炎会导致腹泻症状。","يۇغان ئۈچەي ياللۇغى ئىچ ئۆتۈش ئالامەتلىرىنى كەلتۈرۈپ چىقىرىدۇ.","yughan üchey yallughi ich ötüsh alametlirini keltürüp chiqiridu."]]};
